-- Content. Safe to run more than once: a deck is only inserted if no deck with that title exists.
-- Replace/extend with real word lists (including the YDS words) later.
with seed (deck_title, category, level, deck_position, word_position, english, turkish, part_of_speech, example_en, example_tr, usage_note) as (
  values
  -- A1 · Daily Basics
  ('Daily Basics', 'general', 'A1', 1, 1, 'book', 'kitap', 'noun', 'I read a book every night.', 'Her gece bir kitap okurum.', 'Fiil olarak da kullanılır: "to book" = rezervasyon yapmak.'),
  ('Daily Basics', 'general', 'A1', 1, 2, 'water', 'su', 'noun', 'Can I have a glass of water?', 'Bir bardak su alabilir miyim?', 'Sayılamaz isimdir: "some water", "a glass of water".'),
  ('Daily Basics', 'general', 'A1', 1, 3, 'friend', 'arkadaş', 'noun', 'She is my best friend.', 'O benim en iyi arkadaşım.', '"a friend of mine" = bir arkadaşım.'),
  ('Daily Basics', 'general', 'A1', 1, 4, 'house', 'ev', 'noun', 'They live in a big house.', 'Büyük bir evde yaşıyorlar.', '"house" binayı, "home" ise yaşanılan yeri (yuvayı) anlatır.'),
  ('Daily Basics', 'general', 'A1', 1, 5, 'eat', 'yemek yemek', 'verb', 'We eat dinner at seven.', 'Akşam yemeğini yedide yeriz.', 'Düzensiz fiil: eat – ate – eaten.'),
  -- A1 · Everyday Actions
  ('Everyday Actions', 'general', 'A1', 2, 1, 'go', 'gitmek', 'verb', 'I go to school by bus.', 'Okula otobüsle giderim.', 'Düzensiz fiil: go – went – gone.'),
  ('Everyday Actions', 'general', 'A1', 2, 2, 'want', 'istemek', 'verb', 'I want a cup of tea.', 'Bir fincan çay istiyorum.', '"want to + fiil" şeklinde kullanılır: I want to sleep.'),
  ('Everyday Actions', 'general', 'A1', 2, 3, 'help', 'yardım etmek', 'verb', 'Can you help me, please?', 'Bana yardım eder misin lütfen?', 'İsim olarak da kullanılır: "Thanks for your help."'),
  ('Everyday Actions', 'general', 'A1', 2, 4, 'buy', 'satın almak', 'verb', 'She buys fresh bread every morning.', 'Her sabah taze ekmek alır.', 'Düzensiz fiil: buy – bought – bought.'),
  ('Everyday Actions', 'general', 'A1', 2, 5, 'open', 'açmak', 'verb', 'Please open the window.', 'Lütfen pencereyi aç.', 'Sıfat olarak da kullanılır: "The shop is open." (Dükkân açık.)'),
  -- A2 · Travel
  ('Travel', 'general', 'A2', 1, 1, 'ticket', 'bilet', 'noun', 'I bought two train tickets.', 'İki tren bileti aldım.', '"one-way ticket" = gidiş bileti, "return ticket" = gidiş-dönüş bileti.'),
  ('Travel', 'general', 'A2', 1, 2, 'luggage', 'bagaj', 'noun', 'Where can I leave my luggage?', 'Bagajımı nereye bırakabilirim?', 'Sayılamaz isimdir: "a piece of luggage". Amerikan İngilizcesinde "baggage" da kullanılır.'),
  ('Travel', 'general', 'A2', 1, 3, 'passport', 'pasaport', 'noun', 'Don''t forget your passport.', 'Pasaportunu unutma.', 'Sınır kontrolünde ve havalimanlarında kimlik olarak kullanılır.'),
  ('Travel', 'general', 'A2', 1, 4, 'arrive', 'varmak', 'verb', 'The train arrives at nine.', 'Tren dokuzda varır.', 'Şehir/ülke için "arrive in", yer (istasyon, havalimanı) için "arrive at" kullanılır.'),
  ('Travel', 'general', 'A2', 1, 5, 'delay', 'gecikme; ertelemek', 'noun/verb', 'The flight has a two-hour delay.', 'Uçuşun iki saat rötarı var.', 'İsim: "a delay" (gecikme). Fiil: "The storm delayed the flight." (ertelemek).'),
  -- B1 and B2 · adverbs and linking words
  ('Frequency & Time', 'general', 'B1', 1, 1, 'rarely', 'nadiren', 'adverb', 'He rarely eats meat.', 'O nadiren et yer.', 'Sıklık zarfıdır ve olumsuz anlam taşır, bu yüzden ''not'' ile birlikte kullanılmaz. Genelde ana fiilden önce, ''be'' fiilinden sonra gelir.'),
  ('Frequency & Time', 'general', 'B1', 1, 2, 'frequently', 'sık sık', 'adverb', 'She frequently travels for work.', 'O iş için sık sık seyahat eder.', 'Bir şeyin çok tekrarlandığını anlatır. ''often'' ile aynı anlamdadır ama daha resmidir.'),
  ('Frequency & Time', 'general', 'B1', 1, 3, 'immediately', 'hemen, derhal', 'adverb', 'Call me immediately if there is a problem.', 'Bir sorun olursa beni hemen ara.', 'Zaman kaybetmeden yapılması gereken işler için kullanılır. Uyarı, talimat ve acil durumlarda sık geçer.'),
  ('Frequency & Time', 'general', 'B1', 1, 4, 'recently', 'son zamanlarda', 'adverb', 'I haven''t seen him recently.', 'Onu son zamanlarda görmedim.', 'Yakın geçmişi anlatır. Present perfect veya past simple ile kullanılır: ''I have recently moved.'''),
  ('Frequency & Time', 'general', 'B1', 1, 5, 'currently', 'şu anda', 'adverb', 'She is currently working on a new project.', 'Şu anda yeni bir proje üzerinde çalışıyor.', 'Şu an devam eden durum ve işler için kullanılır, çoğunlukla present continuous ile. ''actually'' ile karıştırılmamalı.'),
  ('Certainty & Opinion', 'general', 'B1', 2, 1, 'apparently', 'görünüşe göre', 'adverb', 'Apparently, the meeting has been cancelled.', 'Görünüşe göre toplantı iptal edilmiş.', 'Duyduğun ya da dışarıdan anladığın bilgiyi, tam emin olmadan aktarırken kullanılır.'),
  ('Certainty & Opinion', 'general', 'B1', 2, 2, 'obviously', 'belli ki, açıkça', 'adverb', 'Obviously, nobody wants to work on weekends.', 'Belli ki kimse hafta sonu çalışmak istemiyor.', 'Herkesin görebileceği kadar açık şeyler için kullanılır. Fazla kullanılırsa küstah duyulabilir.'),
  ('Certainty & Opinion', 'general', 'B1', 2, 3, 'definitely', 'kesinlikle', 'adverb', 'I will definitely come to your party.', 'Partine kesinlikle geleceğim.', 'Bir şeyden tamamen emin olunduğunu vurgular. Konumu: ''will definitely'', ''is definitely''.'),
  ('Certainty & Opinion', 'general', 'B1', 2, 4, 'probably', 'muhtemelen', 'adverb', 'It will probably rain tomorrow.', 'Yarın muhtemelen yağmur yağacak.', 'Gerçekleşme ihtimali yüksek olan şeyler için kullanılır. ''will'' ile sık geçer, olumsuzda ''probably won''t'' denir.'),
  ('Certainty & Opinion', 'general', 'B1', 2, 5, 'unfortunately', 'maalesef, ne yazık ki', 'adverb', 'Unfortunately, the flight was cancelled.', 'Maalesef uçuş iptal edildi.', 'Kötü haber verirken veya özür dilerken, çoğunlukla cümle başında kullanılır.'),
  ('Degree & Result', 'general', 'B1', 3, 1, 'actually', 'aslında', 'adverb', 'I thought it was easy, but actually it was quite difficult.', 'Kolay sanmıştım ama aslında oldukça zordu.', 'Sanılanın aksine gerçeği söylerken veya bir düzeltme yaparken kullanılır. Türkçedeki ''şu an'' anlamına gelmez, o ''currently''.'),
  ('Degree & Result', 'general', 'B1', 3, 2, 'eventually', 'sonunda, nihayetinde', 'adverb', 'After many delays, the bus eventually arrived.', 'Birçok gecikmeden sonra otobüs sonunda geldi.', 'Uzun süre, çaba veya gecikmeden sonra gerçekleşen sonuç için kullanılır. ''Olası'' anlamına gelmez.'),
  ('Degree & Result', 'general', 'B1', 3, 3, 'hardly', 'neredeyse hiç', 'adverb', 'I could hardly hear him because of the noise.', 'Gürültüden dolayı onu neredeyse hiç duyamadım.', 'Cümleye olumsuz anlam katar, bu yüzden ''not'' ile kullanılmaz: ''I can hardly see''. ''hardly ever'' = neredeyse hiçbir zaman. ''hard'' (zor) ile karıştırılmamalı.'),
  ('Degree & Result', 'general', 'B1', 3, 4, 'nearly', 'neredeyse', 'adverb', 'I nearly missed the train this morning.', 'Bu sabah treni neredeyse kaçırıyordum.', 'Bir şeye çok yaklaşıldığını ama gerçekleşmediğini anlatır. ''almost'' ile hemen hemen aynıdır.'),
  ('Degree & Result', 'general', 'B1', 3, 5, 'otherwise', 'aksi takdirde, yoksa', 'adverb', 'Hurry up, otherwise we will miss the bus.', 'Acele et, yoksa otobüsü kaçıracağız.', 'Bir koşul gerçekleşmezse ne olacağını anlatır, ''if not'' anlamındadır.'),
  ('Linking Words', 'general', 'B2', 1, 1, 'therefore', 'bu nedenle, dolayısıyla', 'adverb', 'It was raining; therefore, the match was postponed.', 'Yağmur yağıyordu; bu nedenle maç ertelendi.', 'Sonuç belirten resmi bir bağlaçtır. Yazılı dilde ve sınavlarda sık geçer.'),
  ('Linking Words', 'general', 'B2', 1, 2, 'however', 'ancak, fakat', 'adverb', 'The plan is good. However, it is too expensive.', 'Plan iyi. Ancak çok pahalı.', 'Zıtlık bağlacıdır. Cümle başında ''However,'' diye virgülle kullanılır. ''but''tan daha resmidir.'),
  ('Linking Words', 'general', 'B2', 1, 3, 'meanwhile', 'bu arada', 'adverb', 'Cook the rice. Meanwhile, I will prepare the sauce.', 'Pilavı pişir. Bu arada ben sosu hazırlayacağım.', 'Aynı anda olan iki olayı bağlar veya iki olay arasındaki zamanı anlatır.'),
  ('Linking Words', 'general', 'B2', 1, 4, 'moreover', 'üstelik, dahası', 'adverb', 'The hotel is cheap. Moreover, it is close to the beach.', 'Otel ucuz. Üstelik plaja yakın.', 'Önceki bilgiye bir bilgi daha ekler, resmi dildedir. ''besides'' ve ''in addition'' ile aynı anlamdadır.'),
  ('Linking Words', 'general', 'B2', 1, 5, 'nevertheless', 'yine de, buna rağmen', 'adverb', 'It was risky. Nevertheless, they decided to go.', 'Riskliydi. Buna rağmen gitmeye karar verdiler.', 'Beklenenin tersi bir sonucu anlatan resmi zıtlık bağlacıdır.'),
  ('Manner & Degree', 'general', 'B2', 2, 1, 'gradually', 'yavaş yavaş, giderek', 'adverb', 'The weather gradually got warmer.', 'Hava yavaş yavaş ısındı.', 'Küçük adımlarla ve zamanla olan değişimleri anlatır (hava, beceri, fiyat vb.).'),
  ('Manner & Degree', 'general', 'B2', 2, 2, 'entirely', 'tamamen', 'adverb', 'I entirely agree with you.', 'Seninle tamamen aynı fikirdeyim.', 'Bir şeyin tamamını vurgular, ''completely'' ile aynıdır. ''not entirely'' = tam olarak değil.'),
  ('Manner & Degree', 'general', 'B2', 2, 3, 'merely', 'sadece, yalnızca', 'adverb', 'It was merely a mistake, not a crime.', 'Bu sadece bir hataydı, suç değil.', 'Bir şeyi önemsiz veya küçük göstermek için kullanılır. ''only''nin daha resmi halidir.'),
  ('Manner & Degree', 'general', 'B2', 2, 4, 'deliberately', 'kasıtlı olarak, bilerek', 'adverb', 'He deliberately ignored my message.', 'Mesajımı bilerek görmezden geldi.', 'Bir şeyin kazara değil, planlı ve isteyerek yapıldığını anlatır.'),
  ('Manner & Degree', 'general', 'B2', 2, 5, 'relatively', 'nispeten', 'adverb', 'The test was relatively easy.', 'Sınav nispeten kolaydı.', 'Başka şeylerle kıyaslayarak bir özelliği anlatır. Genelde ''relatively + sıfat'' şeklinde kullanılır.'),
  -- B1 and B2 · prepositions and phrases
  ('Place & Direction', 'general', 'B1', 4, 1, 'among', 'arasında (ikiden fazla şey için)', 'preposition', 'She was sitting among her friends.', 'Arkadaşlarının arasında oturuyordu.', 'İkiden fazla kişi veya şey arasında kullanılır. İki şey arasında ise "between" kullanılır.'),
  ('Place & Direction', 'general', 'B1', 4, 2, 'towards', '-e doğru', 'preposition', 'He walked towards the door.', 'Kapıya doğru yürüdü.', 'Yön belirtir, hedefe varıldığını söylemez. Amerikan İngilizcesinde "toward" da kullanılır.'),
  ('Place & Direction', 'general', 'B1', 4, 3, 'opposite', 'karşısında', 'preposition', 'The bank is opposite the station.', 'Banka istasyonun karşısında.', 'Bir şeyin tam karşısındaki yeri anlatır. Sıfat (zıt) ve isim (zıttı) olarak da kullanılır.'),
  ('Place & Direction', 'general', 'B1', 4, 4, 'within', 'içinde, dahilinde', 'preposition', 'Please reply within two days.', 'Lütfen iki gün içinde cevap verin.', 'Bir süre veya sınır içinde anlamındadır: within a week, within the law, within walking distance.'),
  ('Place & Direction', 'general', 'B1', 4, 5, 'throughout', 'boyunca', 'preposition', 'It rained throughout the night.', 'Bütün gece boyunca yağmur yağdı.', 'Bir sürenin başından sonuna kadar süren durumlar için kullanılır. Yer için de kullanılır: throughout the country (ülkenin her yerinde).'),
  ('Contrast & Choice', 'general', 'B1', 5, 1, 'despite', '-e rağmen', 'preposition', 'Despite the rain, we went for a walk.', 'Yağmura rağmen yürüyüşe çıktık.', 'Zıtlık bildirir. Arkasından isim veya -ing gelir: despite the noise, despite being tired. "despite of" denmez, "in spite of" denir.'),
  ('Contrast & Choice', 'general', 'B1', 5, 2, 'except', 'hariç', 'preposition', 'Everyone came except Tom.', 'Tom hariç herkes geldi.', 'Bir kişiyi veya şeyi kapsam dışı bırakır. "except for" ve "except that" biçimleri de vardır.'),
  ('Contrast & Choice', 'general', 'B1', 5, 3, 'instead of', 'yerine', 'preposition', 'I drank tea instead of coffee.', 'Kahve yerine çay içtim.', 'Bir şeyin yerine başka bir şey seçildiğini anlatır. Arkasından isim veya -ing gelir.'),
  ('Contrast & Choice', 'general', 'B1', 5, 4, 'besides', '-in yanı sıra', 'preposition', 'Besides English, she speaks French.', 'İngilizcenin yanı sıra Fransızca da konuşur.', 'Bir şeye ek olarak başka bir şeyi söylerken kullanılır. "beside" (yanında) ile karıştırılmamalı.'),
  ('Contrast & Choice', 'general', 'B1', 5, 5, 'according to', '-e göre', 'preposition', 'According to the report, sales have increased.', 'Rapora göre satışlar arttı.', 'Bir bilginin kaynağını belirtir. Kendi görüşün için kullanılmaz: "according to me" yanlış, "in my opinion" doğru.'),
  ('Position & Movement', 'general', 'B2', 3, 1, 'beyond', 'ötesinde', 'preposition', 'The village is just beyond the hill.', 'Köy tepenin hemen ötesinde.', 'Bir sınırın ötesini anlatır. Mecazi olarak "sınırı aşan" anlamı da taşır: beyond my control (kontrolüm dışında).'),
  ('Position & Movement', 'general', 'B2', 3, 2, 'beneath', 'altında', 'preposition', 'The keys were beneath the sofa.', 'Anahtarlar koltuğun altındaydı.', '"under" sözcüğünün daha resmi ve edebi hâlidir. Mecazi kullanımı da vardır: beneath his dignity.'),
  ('Position & Movement', 'general', 'B2', 3, 3, 'alongside', 'yanında, ile birlikte', 'preposition', 'He worked alongside his father.', 'Babasıyla birlikte çalıştı.', 'Yan yana veya birlikte anlamındadır. Hem yer hem iş birliği için kullanılır.'),
  ('Position & Movement', 'general', 'B2', 3, 4, 'via', 'aracılığıyla, üzerinden', 'preposition', 'We flew to Rome via Munich.', 'Roma''ya Münih üzerinden uçtuk.', 'Bir yer veya yöntem aracılığıyla anlamındadır: via email, via Istanbul.'),
  ('Position & Movement', 'general', 'B2', 3, 5, 'upon', 'üzerine', 'preposition', 'Upon arrival, please check in at the desk.', 'Varışta lütfen resepsiyonda kayıt yaptırın.', '"on" sözcüğünün daha resmi hâlidir. "upon arrival" (varır varmaz) gibi kalıplarda sık geçer.'),
  ('Reason & Contrast', 'general', 'B2', 4, 1, 'due to', 'nedeniyle, yüzünden', 'preposition', 'The flight was cancelled due to bad weather.', 'Uçuş kötü hava nedeniyle iptal edildi.', 'Nedeni belirtir. Genelde "be" fiilinden sonra veya cümle sonunda kullanılır, "because of" ile benzerdir.'),
  ('Reason & Contrast', 'general', 'B2', 4, 2, 'thanks to', 'sayesinde', 'preposition', 'Thanks to your help, we finished early.', 'Senin sayende erken bitirdik.', 'Genelde olumlu bir nedeni belirtir (sayesinde). Olumsuz neden için "due to" veya "because of" tercih edilir.'),
  ('Reason & Contrast', 'general', 'B2', 4, 3, 'apart from', 'dışında, haricinde', 'preposition', 'Apart from Monday, I am free all week.', 'Pazartesi dışında bütün hafta boşum.', 'Hem "hariç" hem "ek olarak" anlamında kullanılabilir. Anlam bağlamdan anlaşılır.'),
  ('Reason & Contrast', 'general', 'B2', 4, 4, 'unlike', '-in aksine', 'preposition', 'Unlike his brother, he loves sports.', 'Kardeşinin aksine spora bayılır.', 'İki kişi veya şey arasındaki farkı gösterir. Cümle başında virgülle kullanılır.'),
  ('Reason & Contrast', 'general', 'B2', 4, 5, 'regarding', 'ile ilgili olarak', 'preposition', 'I am writing regarding your application.', 'Başvurunuzla ilgili yazıyorum.', 'Resmi yazışmalarda "hakkında" anlamında kullanılır. "about" sözcüğünün daha resmi hâlidir.'),
  ('Formal Phrases', 'general', 'B2', 5, 1, 'amid', 'ortasında', 'preposition', 'She stayed calm amid the chaos.', 'Kaosun ortasında sakin kaldı.', 'Genellikle karmaşa veya gürültü gibi bir ortamın içinde anlamında, resmi yazıda kullanılır.'),
  ('Formal Phrases', 'general', 'B2', 5, 2, 'regardless of', '-e bakılmaksızın', 'preposition', 'He helps everyone regardless of age.', 'Yaşa bakılmaksızın herkese yardım eder.', 'Bir şeyin etkisi olmadığını anlatır. Arkasından isim veya -ing gelir.'),
  ('Formal Phrases', 'general', 'B2', 5, 3, 'prior to', '-den önce', 'preposition', 'Prior to the meeting, we reviewed the plan.', 'Toplantıdan önce planı gözden geçirdik.', '"before" sözcüğünün çok resmi hâlidir. Sınavlarda ve resmi metinlerde sık görülür.'),
  ('Formal Phrases', 'general', 'B2', 5, 4, 'on behalf of', 'adına', 'preposition', 'I am speaking on behalf of the team.', 'Ekip adına konuşuyorum.', 'Başkasının yerine veya onun adına yapılan işleri anlatır.'),
  ('Formal Phrases', 'general', 'B2', 5, 5, 'in addition to', '-e ek olarak', 'preposition', 'In addition to his salary, he gets a bonus.', 'Maaşına ek olarak prim alır.', 'Bir şeye ek olarak başka bir şey söylenirken kullanılır. Arkasından isim veya -ing gelir.')
),
guarded as (
  select * from seed where not exists (select 1 from public.decks d where d.title = seed.deck_title)
),
new_decks as (
  insert into public.decks (title, category, level, position)
  select distinct deck_title, category::public.deck_category, level::public.cefr_level, deck_position
  from guarded
  returning id, title
),
new_words as (
  insert into public.words (english, turkish, part_of_speech, example_en, example_tr, usage_note, level)
  select english, turkish, part_of_speech, example_en, example_tr, usage_note, level::public.cefr_level
  from guarded
  returning id, english
)
insert into public.deck_words (deck_id, word_id, position)
select d.id, w.id, g.word_position
from guarded g
join new_decks d on d.title = g.deck_title
join new_words w on w.english = g.english;

-- YDS decks: the same words as above, grouped in their own category.
-- They link to the existing word rows, so nothing is duplicated.
with yds (deck_title, deck_position, word_position, english) as (
  values
  ('YDS · Frequency & Time', 1, 1, 'rarely'),
  ('YDS · Frequency & Time', 1, 2, 'frequently'),
  ('YDS · Frequency & Time', 1, 3, 'immediately'),
  ('YDS · Frequency & Time', 1, 4, 'recently'),
  ('YDS · Frequency & Time', 1, 5, 'currently'),
  ('YDS · Certainty & Opinion', 2, 1, 'apparently'),
  ('YDS · Certainty & Opinion', 2, 2, 'obviously'),
  ('YDS · Certainty & Opinion', 2, 3, 'definitely'),
  ('YDS · Certainty & Opinion', 2, 4, 'probably'),
  ('YDS · Certainty & Opinion', 2, 5, 'unfortunately'),
  ('YDS · Degree & Result', 3, 1, 'actually'),
  ('YDS · Degree & Result', 3, 2, 'eventually'),
  ('YDS · Degree & Result', 3, 3, 'hardly'),
  ('YDS · Degree & Result', 3, 4, 'nearly'),
  ('YDS · Degree & Result', 3, 5, 'otherwise'),
  ('YDS · Linking Words', 4, 1, 'therefore'),
  ('YDS · Linking Words', 4, 2, 'however'),
  ('YDS · Linking Words', 4, 3, 'meanwhile'),
  ('YDS · Linking Words', 4, 4, 'moreover'),
  ('YDS · Linking Words', 4, 5, 'nevertheless'),
  ('YDS · Manner & Degree', 5, 1, 'gradually'),
  ('YDS · Manner & Degree', 5, 2, 'entirely'),
  ('YDS · Manner & Degree', 5, 3, 'merely'),
  ('YDS · Manner & Degree', 5, 4, 'deliberately'),
  ('YDS · Manner & Degree', 5, 5, 'relatively'),
  ('YDS · Place & Direction', 6, 1, 'among'),
  ('YDS · Place & Direction', 6, 2, 'towards'),
  ('YDS · Place & Direction', 6, 3, 'opposite'),
  ('YDS · Place & Direction', 6, 4, 'within'),
  ('YDS · Place & Direction', 6, 5, 'throughout'),
  ('YDS · Contrast & Choice', 7, 1, 'despite'),
  ('YDS · Contrast & Choice', 7, 2, 'except'),
  ('YDS · Contrast & Choice', 7, 3, 'instead of'),
  ('YDS · Contrast & Choice', 7, 4, 'besides'),
  ('YDS · Contrast & Choice', 7, 5, 'according to'),
  ('YDS · Position & Movement', 8, 1, 'beyond'),
  ('YDS · Position & Movement', 8, 2, 'beneath'),
  ('YDS · Position & Movement', 8, 3, 'alongside'),
  ('YDS · Position & Movement', 8, 4, 'via'),
  ('YDS · Position & Movement', 8, 5, 'upon'),
  ('YDS · Reason & Contrast', 9, 1, 'due to'),
  ('YDS · Reason & Contrast', 9, 2, 'thanks to'),
  ('YDS · Reason & Contrast', 9, 3, 'apart from'),
  ('YDS · Reason & Contrast', 9, 4, 'unlike'),
  ('YDS · Reason & Contrast', 9, 5, 'regarding'),
  ('YDS · Formal Phrases', 10, 1, 'amid'),
  ('YDS · Formal Phrases', 10, 2, 'regardless of'),
  ('YDS · Formal Phrases', 10, 3, 'prior to'),
  ('YDS · Formal Phrases', 10, 4, 'on behalf of'),
  ('YDS · Formal Phrases', 10, 5, 'in addition to')
),
guarded as (
  select * from yds where not exists (select 1 from public.decks d where d.title = yds.deck_title)
),
new_decks as (
  insert into public.decks (title, category, level, position)
  select distinct deck_title, 'yds'::public.deck_category, null::public.cefr_level, deck_position
  from guarded
  returning id, title
)
insert into public.deck_words (deck_id, word_id, position)
select d.id, w.id, g.word_position
from guarded g
join new_decks d on d.title = g.deck_title
join public.words w on w.english = g.english;


-- Grammar topics. Safe to run more than once (slug is unique).
insert into public.grammar_topics (slug, title, level, position, content)
values
  ('to-be', 'To Be (am / is / are)', 'A1', 1, $j${"summary": "\"Olmak\" fiilidir. Kim olduğumuzu, nasıl olduğumuzu, nerede olduğumuzu ve yaşımızı anlatırken kullanılır.", "rules": [{"title": "Öznelere göre değişir", "text": "I → am, he / she / it → is, you / we / they → are."}, {"title": "Kısaltmalar", "text": "I am → I'm, he is → he's, they are → they're, is not → isn't, are not → aren't."}], "forms": [{"label": "Olumlu", "formula": "özne + am / is / are", "examples": [{"en": "I am a student.", "tr": "Ben bir öğrenciyim."}, {"en": "She is happy.", "tr": "O mutlu."}, {"en": "They are at home.", "tr": "Onlar evde."}]}, {"label": "Olumsuz", "formula": "özne + am / is / are + not", "examples": [{"en": "I am not tired.", "tr": "Yorgun değilim."}, {"en": "He isn't here.", "tr": "O burada değil."}]}, {"label": "Soru", "formula": "Am / Is / Are + özne ...?", "examples": [{"en": "Are you ready?", "tr": "Hazır mısın?"}, {"en": "Is she a teacher?", "tr": "O öğretmen mi?"}]}], "signals": [], "notes": ["Soru cümlesinde fiil özneden önce gelir: You are → Are you ...?", "Kısa cevaplarda olumlu formun kısaltması kullanılmaz: Yes, I am. (Yes, I'm. ✗)", "\"I am not\" için \"amn't\" diye bir kısaltma yoktur, \"I'm not\" denir."]}$j$::jsonb),
  ('present-simple', 'Present Simple', 'A1', 2, $j${"summary": "Alışkanlıkları, rutinleri, genel gerçekleri ve değişmeyen durumları anlatır.", "rules": [{"title": "Yapı", "text": "I / you / we / they + fiil, he / she / it + fiil + s / es."}, {"title": "-s / -es kuralı", "text": "-s, -sh, -ch, -x, -o ile bitenlere -es eklenir (watch → watches, go → goes). Ünsüz + y ile bitenlerde y düşer ve -ies gelir (study → studies)."}], "forms": [{"label": "Olumlu", "formula": "özne + fiil (he / she / it için -s)", "examples": [{"en": "I work every day.", "tr": "Her gün çalışırım."}, {"en": "She drinks coffee in the morning.", "tr": "O sabahları kahve içer."}]}, {"label": "Olumsuz", "formula": "özne + do / does + not + yalın fiil", "examples": [{"en": "They don't live here.", "tr": "Onlar burada yaşamıyor."}, {"en": "He doesn't like fish.", "tr": "O balığı sevmez."}]}, {"label": "Soru", "formula": "Do / Does + özne + yalın fiil ...?", "examples": [{"en": "Do you speak English?", "tr": "İngilizce konuşuyor musun?"}, {"en": "Does she work here?", "tr": "O burada mı çalışıyor?"}]}], "signals": ["always", "usually", "often", "sometimes", "never", "every day", "on Mondays"], "notes": ["does / doesn't kullanıldığında ana fiil yalın kalır: She doesn't likes ✗ → She doesn't like ✓", "Sıklık zarfları (always, never ...) genelde ana fiilden önce, \"be\" fiilinden sonra gelir."]}$j$::jsonb),
  ('present-continuous', 'Present Continuous', 'A1', 3, $j${"summary": "Şu anda olan, geçici süren eylemleri ve yakın gelecek için planlanmış işleri anlatır.", "rules": [{"title": "Yapı", "text": "özne + am / is / are + fiil-ing"}, {"title": "Yazım kuralı", "text": "e ile biten fiillerde e düşer (make → making). Tek heceli ve ünsüz-ünlü-ünsüz biten fiillerde son harf ikilenir (run → running, sit → sitting)."}], "forms": [{"label": "Olumlu", "formula": "özne + am / is / are + fiil-ing", "examples": [{"en": "I am reading a book.", "tr": "Bir kitap okuyorum."}, {"en": "They are playing football.", "tr": "Futbol oynuyorlar."}]}, {"label": "Olumsuz", "formula": "özne + am / is / are + not + fiil-ing", "examples": [{"en": "She isn't sleeping.", "tr": "O uyumuyor."}, {"en": "I'm not working today.", "tr": "Bugün çalışmıyorum."}]}, {"label": "Soru", "formula": "Am / Is / Are + özne + fiil-ing ...?", "examples": [{"en": "Are you listening to me?", "tr": "Beni dinliyor musun?"}, {"en": "What is he doing?", "tr": "O ne yapıyor?"}]}], "signals": ["now", "right now", "at the moment", "today", "currently", "these days", "Look!", "Listen!"], "notes": ["Durum fiilleri (know, like, love, want, need, believe ...) genelde -ing almaz: I know ✓, I am knowing ✗", "Yakın gelecek için planlanmış işlerde de kullanılır: I'm meeting him tomorrow."]}$j$::jsonb),
  ('past-simple', 'Past Simple', 'A2', 1, $j${"summary": "Geçmişte başlayıp biten eylemleri anlatır.", "rules": [{"title": "Düzenli fiiller", "text": "Fiile -ed eklenir: work → worked. e ile bitenlere sadece -d (live → lived), ünsüz + y ile bitenlerde -ied (study → studied)."}, {"title": "Düzensiz fiiller", "text": "Kendi biçimleri vardır, ezberlenmelidir: go → went, see → saw, have → had, buy → bought."}], "forms": [{"label": "Olumlu", "formula": "özne + fiil-ed / düzensiz 2. hâl", "examples": [{"en": "I visited my grandmother yesterday.", "tr": "Dün büyükannemi ziyaret ettim."}, {"en": "They went to Izmir last year.", "tr": "Geçen yıl İzmir'e gittiler."}]}, {"label": "Olumsuz", "formula": "özne + did not (didn't) + yalın fiil", "examples": [{"en": "She didn't come to the party.", "tr": "O partiye gelmedi."}, {"en": "We didn't see the film.", "tr": "Filmi izlemedik."}]}, {"label": "Soru", "formula": "Did + özne + yalın fiil ...?", "examples": [{"en": "Did you call him?", "tr": "Onu aradın mı?"}, {"en": "Where did they go?", "tr": "Nereye gittiler?"}]}], "signals": ["yesterday", "last week", "last year", "ago", "in 2020", "when I was a child"], "notes": ["did kullanıldığında ana fiil yalın kalır: Did she went? ✗ → Did she go? ✓", "\"be\" fiilinin geçmişi was / were'dir ve did ile kullanılmaz: I was tired. Were you at home?"]}$j$::jsonb),
  ('future-will-going-to', 'Future: will / going to', 'A2', 2, $j${"summary": "Gelecekteki olayları anlatır. will anlık kararlar ve tahminler, going to önceden verilmiş planlar için kullanılır.", "rules": [{"title": "will", "text": "özne + will + yalın fiil. Anlık karar, söz verme, teklif ve tahmin için kullanılır: I'll help you."}, {"title": "be going to", "text": "özne + am / is / are + going to + yalın fiil. Önceden verilmiş karar, plan ve şimdiki işaretlere dayanan tahminler için kullanılır."}], "forms": [{"label": "Olumlu", "formula": "will + fiil  /  am-is-are going to + fiil", "examples": [{"en": "I will call you later.", "tr": "Seni sonra arayacağım."}, {"en": "We are going to travel next month.", "tr": "Gelecek ay seyahat edeceğiz."}]}, {"label": "Olumsuz", "formula": "will not (won't) + fiil  /  am-is-are not going to + fiil", "examples": [{"en": "He won't be late.", "tr": "O geç kalmayacak."}, {"en": "I'm not going to buy it.", "tr": "Onu satın almayacağım."}]}, {"label": "Soru", "formula": "Will + özne + fiil ...?  /  Am-Is-Are + özne + going to + fiil ...?", "examples": [{"en": "Will you help me?", "tr": "Bana yardım eder misin?"}, {"en": "Are you going to study tonight?", "tr": "Bu gece ders çalışacak mısın?"}]}], "signals": ["tomorrow", "next week", "soon", "in two days", "tonight"], "notes": ["Karar o anda veriliyorsa will, daha önceden verilmişse going to kullanılır: \"The phone is ringing.\" \"I'll get it.\"", "will tüm öznelerle aynıdır ve fiil -s almaz: She will go ✓"]}$j$::jsonb),
  ('present-perfect', 'Present Perfect', 'B1', 1, $j${"summary": "Geçmişte olan ama şimdiyle bağlantısı bulunan olayları anlatır: deneyimler, yeni bitmiş işler ve hâlâ süren durumlar.", "rules": [{"title": "Yapı", "text": "özne + have / has + fiilin 3. hâli (V3)"}, {"title": "V3 nedir?", "text": "Düzenli fiillerde -ed (worked), düzensizlerde kendi biçimi (go → gone, see → seen, eat → eaten)."}, {"title": "have / has", "text": "he / she / it ile has, diğer öznelerle have kullanılır."}], "forms": [{"label": "Olumlu", "formula": "özne + have / has + V3", "examples": [{"en": "I have visited London twice.", "tr": "Londra'yı iki kez ziyaret ettim."}, {"en": "She has finished her homework.", "tr": "Ödevini bitirdi."}]}, {"label": "Olumsuz", "formula": "özne + have / has + not + V3", "examples": [{"en": "We haven't seen him today.", "tr": "Onu bugün görmedik."}, {"en": "He hasn't called yet.", "tr": "O henüz aramadı."}]}, {"label": "Soru", "formula": "Have / Has + özne + V3 ...?", "examples": [{"en": "Have you ever been to Italy?", "tr": "Hiç İtalya'ya gittin mi?"}, {"en": "Has she arrived?", "tr": "O geldi mi?"}]}], "signals": ["ever", "never", "already", "yet", "just", "since", "for", "recently", "so far"], "notes": ["Belirli bir geçmiş zaman ifadesiyle (yesterday, in 2019, last week) kullanılmaz. O durumda Past Simple kullanılır.", "for + süre (for two years), since + başlangıç noktası (since 2022).", "have been to = gidip döndü, have gone to = gitti ve henüz dönmedi."]}$j$::jsonb),
  ('first-conditional', 'First Conditional', 'B1', 2, $j${"summary": "Gelecekte gerçekleşmesi mümkün olan koşulları ve olası sonuçlarını anlatır.", "rules": [{"title": "Yapı", "text": "If + Present Simple, will + yalın fiil"}, {"title": "Sıra değişebilir", "text": "Sonuç cümlesi başa gelirse virgül kullanılmaz: I will call you if I have time."}], "forms": [{"label": "Olumlu", "formula": "If + Present Simple, will + yalın fiil", "examples": [{"en": "If it rains, we will stay at home.", "tr": "Yağmur yağarsa evde kalırız."}, {"en": "If you study, you will pass the exam.", "tr": "Çalışırsan sınavı geçersin."}]}, {"label": "Olumsuz", "formula": "If + özne + don't / doesn't ..., will not (won't) + yalın fiil", "examples": [{"en": "If you don't hurry, you will miss the bus.", "tr": "Acele etmezsen otobüsü kaçırırsın."}, {"en": "She won't come if she is tired.", "tr": "Yorgunsa gelmeyecek."}]}, {"label": "Soru", "formula": "Will + özne + yalın fiil + if + Present Simple ...?", "examples": [{"en": "What will you do if you lose your job?", "tr": "İşini kaybedersen ne yapacaksın?"}, {"en": "Will he help us if we ask?", "tr": "Sorarsak bize yardım eder mi?"}]}], "signals": ["if", "unless", "when", "as soon as"], "notes": ["if cümlesinde will kullanılmaz: If it will rain ✗ → If it rains ✓", "unless = if ... not: Unless you hurry, you will miss the bus."]}$j$::jsonb)
on conflict (slug) do nothing;


-- Grammar exercises (multiple choice). Safe to run more than once.
update public.grammar_topics set content = content || $j${"exercises": [{"sentence": "She ___ a teacher.", "options": ["am", "is", "are"], "answer": 1, "explanation": "he / she / it ile \"is\" kullanılır."}, {"sentence": "They ___ at home.", "options": ["is", "are", "am"], "answer": 1, "explanation": "they ile \"are\" kullanılır."}, {"sentence": "I ___ not tired.", "options": ["am", "is", "are"], "answer": 0, "explanation": "I ile \"am\" kullanılır: I am not tired."}, {"sentence": "___ you ready?", "options": ["Is", "Am", "Are"], "answer": 2, "explanation": "you ile soru cümlesi \"Are you ...?\" şeklinde kurulur."}, {"sentence": "He ___ my brother.", "options": ["are", "is", "am"], "answer": 1, "explanation": "he ile \"is\" kullanılır."}]}$j$::jsonb where slug = 'to-be';
update public.grammar_topics set content = content || $j${"exercises": [{"sentence": "She ___ coffee every morning.", "options": ["drink", "drinks", "drinking"], "answer": 1, "explanation": "he / she / it ile fiile -s eklenir."}, {"sentence": "They ___ like fish.", "options": ["don't", "doesn't", "isn't"], "answer": 0, "explanation": "they ile olumsuzda \"don't\" kullanılır."}, {"sentence": "___ he work here?", "options": ["Do", "Does", "Is"], "answer": 1, "explanation": "he / she / it ile soru \"Does ...?\" ile kurulur."}, {"sentence": "My father ___ to work by bus.", "options": ["go", "goes", "going"], "answer": 1, "explanation": "go fiili he / she / it ile \"goes\" olur."}, {"sentence": "I ___ speak French.", "options": ["doesn't", "don't", "not"], "answer": 1, "explanation": "I ile olumsuzda \"don't\" kullanılır."}]}$j$::jsonb where slug = 'present-simple';
update public.grammar_topics set content = content || $j${"exercises": [{"sentence": "Look! It ___ raining.", "options": ["is", "are", "does"], "answer": 0, "explanation": "it ile \"is\" kullanılır: It is raining."}, {"sentence": "I ___ a book at the moment.", "options": ["read", "am reading", "reads"], "answer": 1, "explanation": "\"at the moment\" Present Continuous işaretidir: am + fiil-ing."}, {"sentence": "They ___ playing football now.", "options": ["is", "are", "am"], "answer": 1, "explanation": "they ile \"are\" kullanılır."}, {"sentence": "She ___ sleeping right now.", "options": ["isn't", "don't", "doesn't"], "answer": 0, "explanation": "Olumsuz: is not (isn't) + fiil-ing."}, {"sentence": "What ___ you doing?", "options": ["is", "are", "do"], "answer": 1, "explanation": "you ile \"are\" kullanılır: What are you doing?"}]}$j$::jsonb where slug = 'present-continuous';
update public.grammar_topics set content = content || $j${"exercises": [{"sentence": "I ___ my grandmother yesterday.", "options": ["visit", "visited", "visiting"], "answer": 1, "explanation": "\"yesterday\" geçmiş zaman işaretidir: fiile -ed eklenir."}, {"sentence": "They ___ to Izmir last year.", "options": ["go", "goes", "went"], "answer": 2, "explanation": "go düzensiz fiildir: go – went – gone."}, {"sentence": "She ___ come to the party.", "options": ["didn't", "don't", "wasn't"], "answer": 0, "explanation": "Geçmişte olumsuz: did not (didn't) + yalın fiil."}, {"sentence": "___ you call him?", "options": ["Do", "Did", "Are"], "answer": 1, "explanation": "Geçmişte soru \"Did + özne + yalın fiil\" ile kurulur."}, {"sentence": "We ___ the film last night.", "options": ["see", "saw", "seen"], "answer": 1, "explanation": "see düzensiz fiildir: see – saw – seen."}]}$j$::jsonb where slug = 'past-simple';
update public.grammar_topics set content = content || $j${"exercises": [{"sentence": "I'm tired. I think I ___ go to bed early.", "options": ["will", "am going", "going to"], "answer": 0, "explanation": "O anda verilen karar için \"will\" kullanılır."}, {"sentence": "Look at those clouds! It ___ rain.", "options": ["will", "is going to", "going"], "answer": 1, "explanation": "Şimdiki işarete dayanan tahminde \"be going to\" kullanılır."}, {"sentence": "He ___ be late. He is always on time.", "options": ["won't", "doesn't", "isn't going"], "answer": 0, "explanation": "Tahminde olumsuz: will not (won't) + yalın fiil."}, {"sentence": "We ___ travel next month. We have already bought the tickets.", "options": ["will", "are going to", "go"], "answer": 1, "explanation": "Önceden verilmiş plan için \"be going to\" kullanılır."}, {"sentence": "___ you help me with this box?", "options": ["Will", "Are", "Do"], "answer": 0, "explanation": "Rica ve teklifte \"Will you ...?\" kullanılır."}]}$j$::jsonb where slug = 'future-will-going-to';
update public.grammar_topics set content = content || $j${"exercises": [{"sentence": "I ___ London twice.", "options": ["have visited", "has visited", "visit"], "answer": 0, "explanation": "I ile \"have\" + V3 kullanılır: have visited."}, {"sentence": "She ___ her homework yet.", "options": ["hasn't finished", "didn't finished", "haven't finished"], "answer": 0, "explanation": "she ile \"hasn't\" + V3 kullanılır; \"yet\" olumsuzda cümle sonuna gelir."}, {"sentence": "___ you ever been to Italy?", "options": ["Did", "Have", "Has"], "answer": 1, "explanation": "you ile soru \"Have you ever ...?\" şeklinde kurulur."}, {"sentence": "He has lived here ___ 2019.", "options": ["for", "since", "ago"], "answer": 1, "explanation": "Başlangıç noktası (2019) ile \"since\" kullanılır."}, {"sentence": "They have lived here ___ ten years.", "options": ["since", "for", "ago"], "answer": 1, "explanation": "Süre (ten years) ile \"for\" kullanılır."}]}$j$::jsonb where slug = 'present-perfect';
update public.grammar_topics set content = content || $j${"exercises": [{"sentence": "If it rains, we ___ at home.", "options": ["stay", "will stay", "stayed"], "answer": 1, "explanation": "Sonuç cümlesinde \"will + yalın fiil\" kullanılır."}, {"sentence": "If you ___ hard, you will pass the exam.", "options": ["study", "will study", "studied"], "answer": 0, "explanation": "if cümlesinde Present Simple kullanılır, will kullanılmaz."}, {"sentence": "She ___ come if she is tired.", "options": ["won't", "doesn't", "didn't"], "answer": 0, "explanation": "Sonuç cümlesinde olumsuz: will not (won't) + yalın fiil."}, {"sentence": "___ you hurry, you will miss the bus.", "options": ["If", "Unless", "When"], "answer": 1, "explanation": "unless = if ... not: Acele etmezsen otobüsü kaçırırsın."}, {"sentence": "If he ___ me, I will tell him.", "options": ["will call", "calls", "called"], "answer": 1, "explanation": "if cümlesinde will kullanılmaz: If he calls ..."}]}$j$::jsonb where slug = 'first-conditional';


-- More words (adjectives, advanced vocabulary, everyday verbs). Each deck is created
-- once (guarded by deck title), together with its YDS twin deck. Words have synonyms.
with seed (deck_title, level, deck_position, word_position, english, turkish, part_of_speech, example_en, example_tr, usage_note, synonyms, yds_title, yds_position) as (
  values
  ('Personality Traits', 'B1', 6, 1, 'reliable', 'güvenilir', 'adjective', 'She is a reliable colleague.', 'O güvenilir bir iş arkadaşı.', 'İnsanlar, makineler ve bilgi kaynakları için kullanılır; güvenip dayanabileceğin anlamındadır. Zıttı: unreliable.', array['trustworthy', 'dependable']::text[], 'YDS · Personality Traits', 11),
  ('Personality Traits', 'B1', 6, 2, 'confident', 'kendinden emin', 'adjective', 'He felt confident before the exam.', 'Sınavdan önce kendinden emin hissediyordu.', 'Kendine veya bir sonuca güvenmeyi anlatır: confident about / in something. İsmi: confidence.', '{}'::text[], 'YDS · Personality Traits', 11),
  ('Personality Traits', 'B1', 6, 3, 'curious', 'meraklı', 'adjective', 'The children were curious about the new teacher.', 'Çocuklar yeni öğretmeni merak ediyordu.', 'Bir şeyi öğrenmek istemeyi anlatır: curious about something. Olumlu bir özelliktir; başkasının işine burnunu sokan için "nosy" kullanılır.', '{}'::text[], 'YDS · Personality Traits', 11),
  ('Personality Traits', 'B1', 6, 4, 'generous', 'cömert', 'adjective', 'He is generous with his time.', 'Zamanı konusunda cömerttir.', 'Para, zaman ve yardım gibi şeyleri paylaşmaya istekli olanlar için kullanılır: generous with / to. Zıttı: stingy.', '{}'::text[], 'YDS · Personality Traits', 11),
  ('Personality Traits', 'B1', 6, 5, 'ambitious', 'hırslı', 'adjective', 'She is an ambitious young lawyer.', 'O hırslı bir genç avukat.', 'Başarmak için güçlü bir istek duyan kişileri ve büyük planları anlatır. Genelde olumludur.', '{}'::text[], 'YDS · Personality Traits', 11),
  ('People & Emotions', 'B1', 7, 1, 'patient', 'sabırlı', 'adjective', 'Be patient, the doctor will see you soon.', 'Sabırlı ol, doktor seni birazdan görecek.', 'Bekleyebilen ve sakin kalabilen kişiyi anlatır. İsim olarak "hasta" anlamı da vardır: a patient in hospital.', '{}'::text[], 'YDS · People & Emotions', 12),
  ('People & Emotions', 'B1', 7, 2, 'anxious', 'endişeli', 'adjective', 'She felt anxious about the interview.', 'Mülakat konusunda endişeliydi.', 'Gelecekteki bir şey için duyulan huzursuzluğu anlatır: anxious about something. "anxious to + fiil" ise bir şeyi çok istemek demektir.', '{}'::text[], 'YDS · People & Emotions', 12),
  ('People & Emotions', 'B1', 7, 3, 'embarrassed', 'utanmış, mahcup', 'adjective', 'He was embarrassed by his mistake.', 'Hatası yüzünden utandı.', 'Bir durum yüzünden mahcup olan kişiyi anlatır. "embarrassing" ise utandıran şeyi anlatır: an embarrassing moment.', '{}'::text[], 'YDS · People & Emotions', 12),
  ('People & Emotions', 'B1', 7, 4, 'grateful', 'minnettar', 'adjective', 'I am grateful for your help.', 'Yardımın için minnettarım.', 'Birine veya bir şeye teşekkür borçlu olduğunu hissetmeyi anlatır: grateful to someone for something.', '{}'::text[], 'YDS · People & Emotions', 12),
  ('People & Emotions', 'B1', 7, 5, 'disappointed', 'hayal kırıklığına uğramış', 'adjective', 'We were disappointed with the result.', 'Sonuçtan hayal kırıklığına uğradık.', 'Beklenti karşılanmayınca duyulan üzüntüyü anlatır: disappointed with / about / in. "disappointing" ise hayal kırıklığı yaratan şeyi anlatır.', '{}'::text[], 'YDS · People & Emotions', 12),
  ('Important & Obvious', 'B2', 6, 1, 'essential', 'çok önemli, vazgeçilmez', 'adjective', 'Water is essential for life.', 'Su hayat için vazgeçilmezdir.', 'Bir şeyin olmadan olamayacağını anlatır: essential for / to. "It is essential that ..." kalıbı sınavlarda sık çıkar.', array['vital', 'crucial']::text[], 'YDS · Important & Obvious', 13),
  ('Important & Obvious', 'B2', 6, 2, 'obvious', 'apaçık, belli', 'adjective', 'It was obvious that he was lying.', 'Yalan söylediği apaçık belliydi.', 'Herkesin kolayca görebileceği şeyleri anlatır. Zarfı: obviously.', array['clear', 'evident']::text[], 'YDS · Important & Obvious', 13),
  ('Important & Obvious', 'B2', 6, 3, 'significant', 'önemli, kayda değer', 'adjective', 'There was a significant increase in prices.', 'Fiyatlarda kayda değer bir artış oldu.', 'Fark edilir derecede büyük veya önemli şeyler için, özellikle sayı ve değişimlerde kullanılır.', array['important', 'major']::text[], 'YDS · Important & Obvious', 13),
  ('Important & Obvious', 'B2', 6, 4, 'efficient', 'verimli', 'adjective', 'This machine is very efficient.', 'Bu makine çok verimli.', 'Az zaman ve enerjiyle iyi sonuç alan kişi, yöntem veya makineleri anlatır. İsmi: efficiency.', '{}'::text[], 'YDS · Important & Obvious', 13),
  ('Important & Obvious', 'B2', 6, 5, 'flexible', 'esnek', 'adjective', 'We offer flexible working hours.', 'Esnek çalışma saatleri sunuyoruz.', 'Kolayca değişebilen veya uyum sağlayabilen şeyleri anlatır: flexible schedule, flexible attitude. Zıttı: rigid, inflexible.', '{}'::text[], 'YDS · Important & Obvious', 13),
  ('Exact & Lasting', 'B2', 7, 1, 'accurate', 'doğru, kesin', 'adjective', 'The report gives an accurate picture of the situation.', 'Rapor durumun doğru bir resmini veriyor.', 'Hatasız ve gerçeğe uygun bilgi ya da ölçümleri anlatır. Zıttı: inaccurate.', array['correct', 'precise']::text[], 'YDS · Exact & Lasting', 14),
  ('Exact & Lasting', 'B2', 7, 2, 'various', 'çeşitli', 'adjective', 'We discussed various topics.', 'Çeşitli konuları tartıştık.', 'Birbirinden farklı birkaç şeyi anlatır. Arkasından çoğul isim gelir: various reasons. İsmi: variety.', '{}'::text[], 'YDS · Exact & Lasting', 14),
  ('Exact & Lasting', 'B2', 7, 3, 'temporary', 'geçici', 'adjective', 'This is only a temporary solution.', 'Bu sadece geçici bir çözüm.', 'Sınırlı bir süre devam eden şeyleri anlatır. Zıttı: permanent.', '{}'::text[], 'YDS · Exact & Lasting', 14),
  ('Exact & Lasting', 'B2', 7, 4, 'permanent', 'kalıcı', 'adjective', 'He is looking for a permanent job.', 'Kalıcı bir iş arıyor.', 'Süresiz veya sonsuza kadar devam edecek şeyleri anlatır. Zıttı: temporary.', '{}'::text[], 'YDS · Exact & Lasting', 14),
  ('Exact & Lasting', 'B2', 7, 5, 'reasonable', 'makul', 'adjective', 'The price seems reasonable.', 'Fiyat makul görünüyor.', 'Mantıklı ve adil olan, ölçüyü aşmayan şeyleri anlatır: reasonable price, reasonable request.', '{}'::text[], 'YDS · Exact & Lasting', 14),
  ('Judging Things', 'B2', 8, 1, 'impressive', 'etkileyici', 'adjective', 'Her English is very impressive.', 'İngilizcesi çok etkileyici.', 'Beğeni ve saygı uyandıran şeyleri anlatır. Etkilenen kişiyi anlatan sıfat: impressed.', '{}'::text[], 'YDS · Judging Things', 15),
  ('Judging Things', 'B2', 8, 2, 'challenging', 'zorlayıcı', 'adjective', 'It was a challenging but rewarding job.', 'Zorlayıcı ama tatmin edici bir işti.', 'Zor olan ama kişiyi geliştiren işleri anlatır. Olumlu bir anlam taşır, sadece "difficult" demek değildir.', '{}'::text[], 'YDS · Judging Things', 15),
  ('Judging Things', 'B2', 8, 3, 'familiar', 'tanıdık', 'adjective', 'Her face looks familiar.', 'Yüzü tanıdık geliyor.', '"familiar to someone" birine tanıdık gelen, "familiar with something" bir şeyi iyi bilen demektir.', '{}'::text[], 'YDS · Judging Things', 15),
  ('Judging Things', 'B2', 8, 4, 'rare', 'nadir', 'adjective', 'This bird is very rare.', 'Bu kuş çok nadir bulunur.', 'Çok az bulunan veya nadiren olan şeyleri anlatır. Zarfı: rarely.', array['uncommon', 'unusual']::text[], 'YDS · Judging Things', 15),
  ('Judging Things', 'B2', 8, 5, 'suitable', 'uygun', 'adjective', 'This movie is not suitable for children.', 'Bu film çocuklar için uygun değil.', 'Belli bir amaç veya kişi için uygun olanı anlatır: suitable for / to.', '{}'::text[], 'YDS · Judging Things', 15),
  ('Academic Verbs I', 'C1', 1, 1, 'alleviate', 'hafifletmek, dindirmek', 'verb', 'This medicine will alleviate the pain.', 'Bu ilaç ağrıyı hafifletecek.', 'Ağrı, yük ve sorun gibi olumsuz şeylerin şiddetini azaltmak için kullanılır. Resmi ve akademik dilde sık geçer.', array['ease', 'relieve']::text[], 'YDS · Academic Verbs I', 16),
  ('Academic Verbs I', 'C1', 1, 2, 'undermine', 'baltalamak, zayıflatmak', 'verb', 'Constant criticism can undermine your confidence.', 'Sürekli eleştiri özgüvenini zayıflatabilir.', 'Bir şeyin temelini yavaş yavaş zayıflatmak anlamındadır. Güven, otorite ve çaba gibi soyut şeylerle kullanılır.', array['weaken', 'sabotage']::text[], 'YDS · Academic Verbs I', 16),
  ('Academic Verbs I', 'C1', 1, 3, 'exacerbate', 'kötüleştirmek, şiddetlendirmek', 'verb', 'The delay only exacerbated the problem.', 'Gecikme sorunu sadece daha da kötüleştirdi.', 'Zaten kötü olan bir durumu daha da kötüleştirmek için kullanılır. Sorun, hastalık ve gerginlikle sık geçer.', array['worsen', 'aggravate']::text[], 'YDS · Academic Verbs I', 16),
  ('Academic Verbs I', 'C1', 1, 4, 'scrutinize', 'dikkatle incelemek', 'verb', 'The committee scrutinized every detail.', 'Komite her ayrıntıyı dikkatle inceledi.', 'Hata veya ayrıntı aramak için bir şeyi çok dikkatli incelemek anlamındadır. İsmi: scrutiny.', array['examine', 'inspect']::text[], 'YDS · Academic Verbs I', 16),
  ('Academic Verbs I', 'C1', 1, 5, 'advocate', 'savunmak, desteklemek', 'verb', 'She advocates for equal pay.', 'Eşit ücreti savunuyor.', 'Bir fikri veya politikayı açıkça desteklemek anlamındadır. İsim olarak "savunucu" da olur: an advocate of peace.', array['support', 'champion']::text[], 'YDS · Academic Verbs I', 16),
  ('Academic Verbs II', 'C1', 2, 1, 'foster', 'teşvik etmek, geliştirmek', 'verb', 'The school fosters creativity.', 'Okul yaratıcılığı teşvik eder.', 'Olumlu bir gelişmenin ortaya çıkmasına yardım etmek için kullanılır: foster cooperation, foster talent.', array['encourage', 'promote']::text[], 'YDS · Academic Verbs II', 17),
  ('Academic Verbs II', 'C1', 2, 2, 'comprehend', 'kavramak, anlamak', 'verb', 'He could not comprehend the instructions.', 'Talimatları kavrayamadı.', '"understand" sözcüğünün daha resmi hâlidir, bir şeyi tam olarak anlamayı vurgular. İsmi: comprehension.', array['grasp', 'understand']::text[], 'YDS · Academic Verbs II', 17),
  ('Academic Verbs II', 'C1', 2, 3, 'diminish', 'azalmak, azaltmak', 'verb', 'Her interest in the subject began to diminish.', 'Konuya olan ilgisi azalmaya başladı.', 'Hem geçişli hem geçişsiz kullanılır: bir şeyi azaltmak veya kendiliğinden azalmak.', array['decrease', 'dwindle']::text[], 'YDS · Academic Verbs II', 17),
  ('Academic Verbs II', 'C1', 2, 4, 'contemplate', 'derin derin düşünmek', 'verb', 'He contemplated moving abroad.', 'Yurt dışına taşınmayı düşündü.', 'Bir konuyu uzun uzun düşünmek veya bir eylemi ciddi olarak tasarlamak için kullanılır. Arkasından -ing gelir.', array['ponder', 'consider']::text[], 'YDS · Academic Verbs II', 17),
  ('Academic Verbs II', 'C1', 2, 5, 'circumvent', 'atlatmak, etrafından dolaşmak', 'verb', 'They found a way to circumvent the rules.', 'Kuralları atlatmanın bir yolunu buldular.', 'Bir kural veya engeli doğrudan çiğnemeden aşmak anlamındadır. Çoğu zaman olumsuz bir tonu vardır.', array['bypass', 'evade']::text[], 'YDS · Academic Verbs II', 17),
  ('Academic Adjectives', 'C1', 3, 1, 'meticulous', 'titiz, çok dikkatli', 'adjective', 'She is meticulous about her work.', 'İşi konusunda çok titizdir.', 'Ayrıntılara aşırı özen gösteren kişi ve işleri anlatır: meticulous planning.', array['thorough', 'painstaking']::text[], 'YDS · Academic Adjectives', 18),
  ('Academic Adjectives', 'C1', 3, 2, 'ubiquitous', 'her yerde bulunan, çok yaygın', 'adjective', 'Smartphones are ubiquitous these days.', 'Akıllı telefonlar bugünlerde her yerde.', 'Her yerde görülen ve çok yaygın olan şeyleri anlatır. Resmi ve akademik dilde kullanılır.', array['omnipresent', 'widespread']::text[], 'YDS · Academic Adjectives', 18),
  ('Academic Adjectives', 'C1', 3, 3, 'inevitable', 'kaçınılmaz', 'adjective', 'Change is inevitable in any career.', 'Değişim her kariyerde kaçınılmazdır.', 'Önlenemeyen şeyleri anlatır. "the inevitable" kaçınılmaz olan şey demektir.', array['unavoidable', 'certain']::text[], 'YDS · Academic Adjectives', 18),
  ('Academic Adjectives', 'C1', 3, 4, 'ambiguous', 'belirsiz, muğlak', 'adjective', 'The instructions were ambiguous.', 'Talimatlar belirsizdi.', 'Birden fazla anlama gelebilen ifadeleri anlatır. İsmi: ambiguity.', array['vague', 'unclear']::text[], 'YDS · Academic Adjectives', 18),
  ('Academic Adjectives', 'C1', 3, 5, 'resilient', 'dayanıklı, çabuk toparlanan', 'adjective', 'Children are often more resilient than adults.', 'Çocuklar çoğu zaman yetişkinlerden daha çabuk toparlanır.', 'Zorluk ve sıkıntıdan çabuk toparlanabilen kişi veya sistemleri anlatır. İsmi: resilience.', array['tough', 'adaptable']::text[], 'YDS · Academic Adjectives', 18),
  ('Adjectives & Nouns', 'C1', 4, 1, 'profound', 'derin, köklü', 'adjective', 'The war had a profound effect on him.', 'Savaşın onun üzerinde derin bir etkisi oldu.', 'Etkisi veya anlamı çok derin olan şeyleri anlatır: profound change, profound silence.', array['deep', 'intense']::text[], 'YDS · Adjectives & Nouns', 19),
  ('Adjectives & Nouns', 'C1', 4, 2, 'obsolete', 'modası geçmiş, artık kullanılmayan', 'adjective', 'Typewriters are now obsolete.', 'Daktilolar artık modası geçmiş durumda.', 'Yenisi çıktığı için artık kullanılmayan şeyleri anlatır.', array['outdated', 'outmoded']::text[], 'YDS · Adjectives & Nouns', 19),
  ('Adjectives & Nouns', 'C1', 4, 3, 'drawback', 'dezavantaj, sakınca', 'noun', 'The main drawback is the high price.', 'Asıl sakınca yüksek fiyat.', 'Bir planın veya ürünün olumsuz yönünü anlatır. Genelde "advantage" ile karşılaştırılır.', array['disadvantage', 'downside']::text[], 'YDS · Adjectives & Nouns', 19),
  ('Adjectives & Nouns', 'C1', 4, 4, 'dilemma', 'ikilem', 'noun', 'She faced a difficult dilemma.', 'Zor bir ikilemle karşı karşıya kaldı.', 'İki kötü veya eşit derecede zor seçenek arasında kalma durumunu anlatır: in a dilemma.', array['predicament', 'quandary']::text[], 'YDS · Adjectives & Nouns', 19),
  ('Adjectives & Nouns', 'C1', 4, 5, 'endeavor', 'çaba, girişim', 'noun', 'We wish you success in your future endeavors.', 'Gelecekteki girişimlerinde başarılar dileriz.', 'Bir amaca ulaşmak için gösterilen ciddi çabayı anlatır. Fiil olarak da kullanılır. İngiliz İngilizcesinde yazılışı "endeavour" şeklindedir.', array['effort', 'undertaking']::text[], 'YDS · Adjectives & Nouns', 19),
  ('Useful Verbs I', 'B1', 8, 1, 'achieve', 'başarmak, elde etmek', 'verb', 'She achieved her goal.', 'Hedefine ulaştı.', 'Çaba ve beceriyle bir sonuca ulaşmak anlamındadır: achieve success, achieve a goal. İsmi: achievement.', array['accomplish', 'attain']::text[], 'YDS · Useful Verbs I', 20),
  ('Useful Verbs I', 'B1', 8, 2, 'improve', 'geliştirmek', 'verb', 'I want to improve my English.', 'İngilizcemi geliştirmek istiyorum.', 'Bir şeyi daha iyi hâle getirmek veya kendiliğinden daha iyi olmak için kullanılır. İsmi: improvement.', array['enhance', 'boost']::text[], 'YDS · Useful Verbs I', 20),
  ('Useful Verbs I', 'B1', 8, 3, 'increase', 'artırmak', 'verb', 'Prices increased by ten percent.', 'Fiyatlar yüzde on arttı.', 'Hem fiil hem isim olarak kullanılır: an increase in prices. Zıttı: decrease.', array['raise', 'boost']::text[], 'YDS · Useful Verbs I', 20),
  ('Useful Verbs I', 'B1', 8, 4, 'reduce', 'azaltmak', 'verb', 'We need to reduce costs.', 'Maliyetleri azaltmamız gerekiyor.', 'Miktarı, sayıyı veya boyutu küçültmek anlamındadır: reduce costs, reduce stress.', array['decrease', 'cut']::text[], 'YDS · Useful Verbs I', 20),
  ('Useful Verbs I', 'B1', 8, 5, 'suggest', 'önermek', 'verb', 'I suggest taking a taxi.', 'Taksi tutmayı öneririm.', 'Arkasından -ing veya "that" cümlesi gelir: suggest doing, suggest that he go. "suggest to + fiil" yanlıştır.', array['recommend', 'propose']::text[], 'YDS · Useful Verbs I', 20),
  ('Useful Verbs II', 'B1', 9, 1, 'avoid', 'kaçınmak', 'verb', 'Try to avoid fast food.', 'Fast food''dan kaçınmaya çalış.', 'Arkasından isim veya -ing gelir: avoid making mistakes. Arkasına "to + fiil" gelmez.', array['prevent', 'escape']::text[], 'YDS · Useful Verbs II', 21),
  ('Useful Verbs II', 'B1', 9, 2, 'require', 'gerektirmek', 'verb', 'This job requires experience.', 'Bu iş deneyim gerektirir.', 'Bir şeyin gerekli olduğunu belirtir; kurallar ve zorunluluklarda sık geçer. "be required to" -mek zorunda olmak demektir.', array['need', 'demand']::text[], 'YDS · Useful Verbs II', 21),
  ('Useful Verbs II', 'B1', 9, 3, 'provide', 'sağlamak', 'verb', 'The hotel provides free breakfast.', 'Otel ücretsiz kahvaltı sağlıyor.', '"provide something for someone" veya "provide someone with something" şeklinde kullanılır.', array['supply', 'offer']::text[], 'YDS · Useful Verbs II', 21),
  ('Useful Verbs II', 'B1', 9, 4, 'consider', 'düşünmek, göz önünde bulundurmak', 'verb', 'We are considering a new plan.', 'Yeni bir planı düşünüyoruz.', 'Karar vermeden önce bir şeyi ciddi şekilde düşünmek anlamındadır. Arkasından -ing gelir: consider moving.', array['think about', 'take into account']::text[], 'YDS · Useful Verbs II', 21),
  ('Useful Verbs II', 'B1', 9, 5, 'deal with', 'ilgilenmek, başa çıkmak', 'verb', 'How do you deal with stress?', 'Stresle nasıl başa çıkıyorsun?', 'Bir sorun, kişi veya işle ilgilenip çözmek için kullanılır. Birleşik fiil olduğu için "deal with" birlikte kullanılır.', array['handle', 'cope with']::text[], 'YDS · Useful Verbs II', 21),
  ('Goals & Advantages', 'B1', 10, 1, 'ancient', 'antik, çok eski', 'adjective', 'They visited an ancient temple.', 'Antik bir tapınağı ziyaret ettiler.', 'Tarihin çok eski dönemlerine ait şeyleri anlatır: ancient Rome, ancient history.', array['old', 'historic']::text[], 'YDS · Goals & Advantages', 22),
  ('Goals & Advantages', 'B1', 10, 2, 'advantage', 'avantaj', 'noun', 'Speaking two languages is a big advantage.', 'İki dil konuşmak büyük bir avantaj.', '"take advantage of" bir fırsattan yararlanmak demektir. Zıttı: disadvantage.', array['benefit', 'plus']::text[], 'YDS · Goals & Advantages', 22),
  ('Goals & Advantages', 'B1', 10, 3, 'opportunity', 'fırsat', 'noun', 'This is a great opportunity to learn.', 'Bu öğrenmek için harika bir fırsat.', 'Bir şeyi yapma şansı sunan uygun durumu anlatır: have the opportunity to, miss an opportunity.', array['chance', 'opening']::text[], 'YDS · Goals & Advantages', 22),
  ('Goals & Advantages', 'B1', 10, 4, 'goal', 'hedef', 'noun', 'My goal is to pass the exam.', 'Hedefim sınavı geçmek.', 'Ulaşılmak istenen amacı anlatır: set a goal, achieve a goal. Futbolda "gol" anlamına da gelir.', array['aim', 'target']::text[], 'YDS · Goals & Advantages', 22)
),
guarded as (
  select * from seed where not exists (select 1 from public.decks d where d.title = seed.deck_title)
),
new_decks as (
  insert into public.decks (title, category, level, position)
  select distinct deck_title, 'general'::public.deck_category, level::public.cefr_level, deck_position
  from guarded
  returning id, title
),
new_yds_decks as (
  insert into public.decks (title, category, level, position)
  select distinct yds_title, 'yds'::public.deck_category, null::public.cefr_level, yds_position
  from guarded
  returning id, title
),
new_words as (
  insert into public.words (english, turkish, part_of_speech, example_en, example_tr, usage_note, level, synonyms)
  select english, turkish, part_of_speech, example_en, example_tr, usage_note, level::public.cefr_level, synonyms
  from guarded
  returning id, english
),
level_links as (
  insert into public.deck_words (deck_id, word_id, position)
  select d.id, w.id, g.word_position
  from guarded g
  join new_decks d on d.title = g.deck_title
  join new_words w on w.english = g.english
  returning 1
)
insert into public.deck_words (deck_id, word_id, position)
select y.id, w.id, g.word_position
from guarded g
join new_yds_decks y on y.title = g.yds_title
join new_words w on w.english = g.english;


-- Words that were hard to remember: connectors, fixed phrases and phrasal verbs.
-- Each deck is created once (guarded by deck title), together with its YDS twin deck.
with seed (deck_title, level, deck_position, word_position, english, turkish, part_of_speech, example_en, example_tr, usage_note, synonyms, yds_title, yds_position) as (
  values
  ('Ways & Limits', 'B2', 9, 1, 'by means of', 'yoluyla, vasıtasıyla', 'preposition', 'He communicated by means of sign language.', 'İşaret diliyle iletişim kurdu.', 'Bir işin hangi yöntemle yapıldığını belirtir. Resmi bir kalıptır, günlük dilde "by" veya "using" kullanılır.', array['through', 'using']::text[], 'YDS · Ways & Limits', 23),
  ('Ways & Limits', 'B2', 9, 2, 'by no means', 'asla, hiçbir şekilde', 'adverb', 'She is by no means lazy.', 'O hiçbir şekilde tembel değil.', 'Olumsuz anlamlıdır. Cümle başına gelirse devrik olur: By no means should you open the door.', array['not at all', 'in no way']::text[], 'YDS · Ways & Limits', 23),
  ('Ways & Limits', 'B2', 9, 3, 'in any case', 'her halükarda, ne olursa olsun', 'adverb', 'In any case, we have to finish today.', 'Her halükarda bugün bitirmek zorundayız.', 'Bir durum ne olursa olsun sonucun değişmediğini söyler. "anyway" ile benzerdir.', array['anyway', 'at any rate']::text[], 'YDS · Ways & Limits', 23),
  ('Ways & Limits', 'B2', 9, 4, 'to some degree', 'bir dereceye kadar, bir ölçüde', 'adverb', 'I agree with you to some degree.', 'Seninle bir dereceye kadar aynı fikirdeyim.', 'Bir şeyin tam değil kısmen doğru olduğunu anlatır. "to a certain degree" ve "to some extent" aynı anlamdadır.', array['to a certain degree', 'to some extent']::text[], 'YDS · Ways & Limits', 23),
  ('Ways & Limits', 'B2', 9, 5, 'as far as', '-e gelince, -dığım kadarıyla, -e kadar', 'conjunction', 'As far as I know, the shop is closed.', 'Bildiğim kadarıyla dükkân kapalı.', '"as far as I know" bildiğim kadarıyla, "as far as ... is concerned" ... açısından demektir. Mesafe için de kullanılır: as far as the station.', array['so far as']::text[], 'YDS · Ways & Limits', 23),
  ('Quantity & Habit', 'B2', 10, 1, 'as long as', '-dıkça, -mek koşuluyla', 'conjunction', 'You can stay as long as you keep quiet.', 'Sessiz kaldığın sürece kalabilirsin.', 'Koşul ve süre bildirir. Cümlede Present Simple kullanılır, will kullanılmaz.', array['so long as', 'provided that']::text[], 'YDS · Quantity & Habit', 24),
  ('Quantity & Habit', 'B2', 10, 2, 'as much as', '-ebildiğince, kadar', 'conjunction', 'Eat as much as you like.', 'Canının istediği kadar ye.', 'Miktar karşılaştırır. Zıtlık da anlatabilir: As much as I like him, I can''t trust him. (Onu sevsem de güvenemiyorum.)', '{}'::text[], 'YDS · Quantity & Habit', 24),
  ('Quantity & Habit', 'B2', 10, 3, 'as usual', 'her zamanki gibi', 'adverb', 'As usual, he was late.', 'Her zamanki gibi geç kaldı.', 'Alışılmış durumu anlatır. Cümle başına veya sonuna gelebilir.', array['as always']::text[], 'YDS · Quantity & Habit', 24),
  ('Quantity & Habit', 'B2', 10, 4, 'considering', 'göz önüne alındığında, -e göre', 'preposition', 'Considering his age, he runs very fast.', 'Yaşını düşünürsek çok hızlı koşuyor.', 'Bir durumu hesaba katarak yorum yapar. Arkasından isim, -ing veya "that" gelir.', array['given', 'taking into account']::text[], 'YDS · Quantity & Habit', 24),
  ('Quantity & Habit', 'B2', 10, 5, 'such as', 'örneğin, gibi', 'preposition', 'I like fruit such as apples and pears.', 'Elma ve armut gibi meyveleri severim.', 'Örnek vermek için kullanılır. "like" ile benzerdir ama daha resmidir.', array['for example', 'like']::text[], 'YDS · Quantity & Habit', 24),
  ('Condition I', 'B2', 11, 1, 'even if', 'olsa bile', 'conjunction', 'I will go even if it rains.', 'Yağmur yağsa bile gideceğim.', 'Koşulun sonucu değiştirmediğini anlatır. Gerçek bir durum için "even though" kullanılır.', '{}'::text[], 'YDS · Condition I', 25),
  ('Condition I', 'B2', 11, 2, 'given that', 'göz önüne alındığında, -dığına göre', 'conjunction', 'Given that he is only ten, his score is impressive.', 'Sadece on yaşında olduğu düşünülürse puanı etkileyici.', 'Bilinen bir gerçeği dayanak alıp sonuç çıkarır.', array['considering that', 'seeing that']::text[], 'YDS · Condition I', 25),
  ('Condition I', 'B2', 11, 3, 'assuming that', 'varsayarsak, ... olduğunu varsayarsak', 'conjunction', 'Assuming that the train is on time, we will arrive at six.', 'Tren zamanında olursa altıda varırız.', 'Doğru olduğu varsayılan bir koşul kurar. Arkasından cümle gelir.', array['supposing that', 'presuming that']::text[], 'YDS · Condition I', 25),
  ('Condition I', 'B2', 11, 4, 'suppose', 'diyelim ki, farz edelim', 'conjunction', 'Suppose you won the lottery, what would you do?', 'Diyelim ki piyangoyu kazandın, ne yapardın?', 'Varsayımsal durum kurar. "supposing" ile aynıdır. Gerçek dışı durumlarda Past Simple kullanılır.', array['supposing', 'what if']::text[], 'YDS · Condition I', 25),
  ('Condition I', 'B2', 11, 5, 'providing that', 'koşuluyla', 'conjunction', 'You can go out provided that you finish your homework.', 'Ödevini bitirmen koşuluyla dışarı çıkabilirsin.', 'Bir şeyin ancak bir koşulla olacağını söyler. "providing" ve "provided" aynıdır, "that" düşebilir.', array['provided that', 'as long as']::text[], 'YDS · Condition I', 25),
  ('Condition II', 'B2', 12, 1, 'but for', 'olmasaydı', 'preposition', 'But for your help, I would have failed.', 'Senin yardımın olmasaydı başarısız olurdum.', 'Arkasından isim gelir ve "eğer ... olmasaydı" anlamı verir. Genelde Type 2 veya Type 3 koşulla kullanılır.', array['without', 'if it were not for']::text[], 'YDS · Condition II', 26),
  ('Condition II', 'B2', 12, 2, 'only if', 'ancak ... ise', 'conjunction', 'I will go only if you come with me.', 'Ancak sen benimle gelirsen giderim.', 'Tek koşulu belirtir. Cümle başına gelirse devrik olur: Only if you ask will he help.', '{}'::text[], 'YDS · Condition II', 26),
  ('Condition II', 'B2', 12, 3, 'except if', '... durumu hariç', 'conjunction', 'Don''t call me except if it''s urgent.', 'Acil olmadıkça beni arama.', '"unless" anlamına yakındır, istisna durumu belirtir.', array['unless']::text[], 'YDS · Condition II', 26),
  ('Condition II', 'B2', 12, 4, 'in case', '-me ihtimaline karşı', 'conjunction', 'Take an umbrella in case it rains.', 'Yağmur yağma ihtimaline karşı şemsiye al.', 'Önlem almayı anlatır. Arkasındaki cümle Present Simple olur. "if" ile karıştırılmamalı: in case = önlem için, if = o durumda.', array['just in case', 'lest']::text[], 'YDS · Condition II', 26),
  ('Condition II', 'B2', 12, 5, 'in case of', '-i durumunda', 'preposition', 'In case of fire, use the stairs.', 'Yangın durumunda merdivenleri kullanın.', 'Arkasından isim gelir. Uyarılarda ve resmi duyurularda sık geçer.', array['in the event of']::text[], 'YDS · Condition II', 26),
  ('Hypothesis & Pairs', 'B2', 13, 1, 'what if', 'ya ... olursa?', 'conjunction', 'What if he doesn''t come?', 'Ya gelmezse?', 'Olası bir durumun sonucunu sorgular, endişe veya merak bildirir. Present Simple veya Past Simple ile kullanılır.', array['suppose']::text[], 'YDS · Hypothesis & Pairs', 27),
  ('Hypothesis & Pairs', 'B2', 13, 2, 'both … and', 'hem ... hem de', 'conjunction', 'She speaks both English and French.', 'Hem İngilizce hem Fransızca konuşuyor.', 'İki şeyi birlikte sayar. İki yan aynı türde (paralel) olmalıdır. Fiil çoğul olur.', '{}'::text[], 'YDS · Hypothesis & Pairs', 27),
  ('Hypothesis & Pairs', 'B2', 13, 3, 'not only … but also', 'sadece ... değil, ... da', 'conjunction', 'He is not only smart but also kind.', 'O sadece zeki değil, aynı zamanda nazik.', 'İkinci bilgiyi vurgular. Cümle "Not only" ile başlarsa devrik olur: Not only did he come, but he also helped.', '{}'::text[], 'YDS · Hypothesis & Pairs', 27),
  ('Hypothesis & Pairs', 'B2', 13, 4, 'either … or', 'ya ... ya da', 'conjunction', 'You can either stay or go.', 'Ya kalabilirsin ya da gidebilirsin.', 'İki seçenekten birini belirtir. Fiil, yakın olan özneye uyar.', '{}'::text[], 'YDS · Hypothesis & Pairs', 27),
  ('Hypothesis & Pairs', 'B2', 13, 5, 'neither … nor', 'ne ... ne de', 'conjunction', 'Neither Tom nor Anna was there.', 'Ne Tom ne de Anna oradaydı.', 'İki şeyi de olumsuzlar, bu yüzden fiil olumlu biçimde kullanılır. Fiil yakın özneye uyar.', '{}'::text[], 'YDS · Hypothesis & Pairs', 27),
  ('Timing Phrases', 'B2', 14, 1, 'hardly … when', 'tam ... olmuştu ki', 'conjunction', 'Hardly had I arrived when it started to rain.', 'Tam varmıştım ki yağmur başladı.', 'Bir olayın hemen ardından başka bir olay olduğunu anlatır. Hardly başa gelirse had + özne + V3 kullanılır. "barely" ve "scarcely" aynıdır, "no sooner ... than" benzerdir.', array['barely … when', 'scarcely … when']::text[], 'YDS · Timing Phrases', 28),
  ('Timing Phrases', 'B2', 14, 2, 'afterwards', 'sonradan, daha sonra', 'adverb', 'We had dinner and went for a walk afterwards.', 'Akşam yemeği yedik, sonra yürüyüşe çıktık.', 'Bir olaydan sonra gelen zamanı anlatır, arkasına isim almaz. "after" ise isim veya cümle alır.', array['later', 'subsequently']::text[], 'YDS · Timing Phrases', 28),
  ('Timing Phrases', 'B2', 14, 3, 'in the meantime', 'bu arada', 'adverb', 'The food will be ready soon. In the meantime, let''s set the table.', 'Yemek birazdan hazır. Bu arada masayı kuralım.', 'İki olay arasında geçen süreyi anlatır. "meanwhile" ile aynı anlamdadır.', array['meanwhile']::text[], 'YDS · Timing Phrases', 28),
  ('Timing Phrases', 'B2', 14, 4, 'by the way', 'bu arada, aklıma gelmişken', 'adverb', 'By the way, did you call Tom?', 'Aklıma gelmişken, Tom''u aradın mı?', 'Konudan hafifçe sapmak için kullanılır. "in the meantime" ile karıştırılmamalı.', array['incidentally']::text[], 'YDS · Timing Phrases', 28),
  ('Timing Phrases', 'B2', 14, 5, 'in the end', 'sonunda', 'adverb', 'In the end, we decided to stay home.', 'Sonunda evde kalmaya karar verdik.', 'Uzun düşünce veya süreçten sonra gelen sonucu anlatır. "at the end of" ise bir şeyin sonunu belirtir.', array['finally', 'eventually']::text[], 'YDS · Timing Phrases', 28),
  ('Reasons I', 'C1', 5, 1, 'seeing that', '-dığı için, -dığına göre', 'conjunction', 'Seeing that it was late, we went home.', 'Geç olduğu için eve gittik.', 'Açıkça bilinen bir nedeni belirtir. "since", "as" ve "now that" ile aynı anlamdadır. "as" (-dığı için) de bu gruba girer.', array['as', 'since', 'now that']::text[], 'YDS · Reasons I', 29),
  ('Reasons I', 'C1', 5, 2, 'on the grounds that', '-dığı gerekçesiyle', 'conjunction', 'He refused on the grounds that he was busy.', 'Meşgul olduğu gerekçesiyle reddetti.', 'Bir eylemin gerekçesini resmi biçimde verir.', array['because', 'since']::text[], 'YDS · Reasons I', 29),
  ('Reasons I', 'C1', 5, 3, 'in as much as', '-dığı ölçüde, -dığı için', 'conjunction', 'The plan is good in as much as it saves money.', 'Plan, para tasarrufu sağladığı ölçüde iyidir.', 'Hem neden hem sınırlama bildirebilen resmi bir kalıptır. "inasmuch as" şeklinde birleşik de yazılır.', array['inasmuch as', 'insofar as']::text[], 'YDS · Reasons I', 29),
  ('Reasons I', 'C1', 5, 4, 'on account of', '-den dolayı', 'preposition', 'The match was cancelled on account of rain.', 'Maç yağmur yüzünden iptal edildi.', 'Nedeni belirtir, arkasından isim gelir. "because of" ile aynıdır, daha resmidir.', array['because of', 'due to']::text[], 'YDS · Reasons I', 29),
  ('Reasons I', 'C1', 5, 5, 'in view of', '-i göz önünde bulundurarak, -den dolayı', 'preposition', 'In view of the weather, the trip was postponed.', 'Hava durumu nedeniyle gezi ertelendi.', 'Bir durumu hesaba katarak alınan kararı anlatır.', array['considering', 'given']::text[], 'YDS · Reasons I', 29),
  ('Reasons II', 'C1', 6, 1, 'owing to', '-den dolayı, yüzünden', 'preposition', 'Owing to illness, he missed the exam.', 'Hastalığı yüzünden sınavı kaçırdı.', 'Nedeni belirtir. "due to" ve "because of" ile aynı anlamdadır. Arkasından isim gelir.', array['because of', 'due to']::text[], 'YDS · Reasons II', 30),
  ('Reasons II', 'C1', 6, 2, 'hence', 'bu nedenle, dolayısıyla', 'adverb', 'The road is closed, hence the delay.', 'Yol kapalı, bu nedenle gecikme var.', 'Sonuç bildirir, resmi yazıda kullanılır. Arkasından cümle veya isim gelir. "therefore" ile eşdeğerdir.', array['therefore', 'thus']::text[], 'YDS · Reasons II', 30),
  ('Reasons II', 'C1', 6, 3, 'thereby', 'böylece, bu yolla', 'adverb', 'He signed the contract, thereby accepting the terms.', 'Sözleşmeyi imzaladı ve böylece şartları kabul etmiş oldu.', 'Bir eylemin sonucunu belirtir. Çoğunlukla -ing ile kullanılır.', array['thus', 'by that means']::text[], 'YDS · Reasons II', 30),
  ('Reasons II', 'C1', 6, 4, 'for all', '-e rağmen', 'preposition', 'For all his wealth, he is unhappy.', 'Tüm zenginliğine rağmen mutsuz.', 'Zıtlık bildirir, "despite" anlamındadır. "for all that" buna rağmen demektir.', array['despite', 'in spite of']::text[], 'YDS · Reasons II', 30),
  ('Reasons II', 'C1', 6, 5, 'even so', 'buna rağmen, yine de', 'adverb', 'It was raining. Even so, we went out.', 'Yağmur yağıyordu. Buna rağmen dışarı çıktık.', 'Önceki cümleyle zıt bir durumu başlatır. "nevertheless" ile benzerdir.', array['nevertheless', 'nonetheless']::text[], 'YDS · Reasons II', 30),
  ('Contrast I', 'C1', 7, 1, 'after all', 'sonuçta, ne de olsa', 'adverb', 'Don''t be angry; he is only a child after all.', 'Kızma, ne de olsa o sadece bir çocuk.', 'İki anlamı vardır: "ne de olsa" (hatırlatma) ve cümle sonunda "beklenenin aksine, sonunda": I went after all.', array['all things considered']::text[], 'YDS · Contrast I', 31),
  ('Contrast I', 'C1', 7, 2, 'all the same', 'yine de', 'adverb', 'I''m busy, but I''ll help you all the same.', 'Meşgulüm ama yine de sana yardım edeceğim.', 'Zıtlık bildirir. "nevertheless" ve "even so" ile aynıdır, konuşma dilinde sık kullanılır.', array['nevertheless', 'even so']::text[], 'YDS · Contrast I', 31),
  ('Contrast I', 'C1', 7, 3, 'whereas', 'oysa, ... iken', 'conjunction', 'He likes tea, whereas she prefers coffee.', 'O çayı sever, oysa o kahveyi tercih eder.', 'İki şeyi karşılaştırıp aralarındaki farkı gösterir. Cümle başında da kullanılır.', array['while', 'whilst']::text[], 'YDS · Contrast I', 31),
  ('Contrast I', 'C1', 7, 4, 'in contrast to', '-in aksine', 'preposition', 'In contrast to his brother, he is very quiet.', 'Ağabeyinin aksine çok sessiz.', 'İki durum arasındaki zıtlığı gösterir. "as opposed to" ve "unlike" ile aynı anlamdadır.', array['as opposed to', 'unlike']::text[], 'YDS · Contrast I', 31),
  ('Contrast I', 'C1', 7, 5, 'whilst', '-iken, oysa', 'conjunction', 'Whilst I agree with you, I think there are other options.', 'Sana katılsam da başka seçenekler olduğunu düşünüyorum.', '"while" sözcüğünün resmi İngiliz İngilizcesindeki hâlidir. Zaman ve zıtlık anlamı taşır.', array['while', 'whereas']::text[], 'YDS · Contrast I', 31),
  ('Contrast II', 'C1', 8, 1, 'notwithstanding', '-e rağmen', 'preposition', 'Notwithstanding the cost, they bought the house.', 'Maliyete rağmen evi aldılar.', 'Çok resmi bir zıtlık sözcüğüdür. İsimden önce veya sonra gelebilir: the cost notwithstanding.', array['despite', 'in spite of']::text[], 'YDS · Contrast II', 32),
  ('Contrast II', 'C1', 8, 2, 'or else', 'yoksa, aksi halde', 'conjunction', 'Hurry up, or else we will be late.', 'Acele et, yoksa geç kalacağız.', 'Bir koşul gerçekleşmezse ne olacağını söyler. "otherwise" ile aynıdır, daha çok konuşma dilinde kullanılır.', array['otherwise']::text[], 'YDS · Contrast II', 32),
  ('Contrast II', 'C1', 8, 3, 'but even so', 'ama buna rağmen', 'conjunction', 'It was cheap, but even so I didn''t buy it.', 'Ucuzdu ama buna rağmen almadım.', '"but" ile "even so" birlikte zıtlığı güçlendirir.', array['but still']::text[], 'YDS · Contrast II', 32),
  ('Contrast II', 'C1', 8, 4, 'if so', 'öyleyse', 'adverb', 'Are you hungry? If so, let''s eat.', 'Acıktın mı? Öyleyse yemek yiyelim.', 'Önceki cümledeki durumun doğru olduğunu varsayar. Soru sorduktan sonra kullanılır.', array['in that case']::text[], 'YDS · Contrast II', 32),
  ('Contrast II', 'C1', 8, 5, 'if not', 'değilse, yoksa', 'adverb', 'Is he coming? If not, we will start without him.', 'Geliyor mu? Gelmiyorsa onsuz başlarız.', 'Önceki cümledeki durumun doğru olmadığını varsayar. Ayrıca "hatta" anlamında da kullanılır: very good, if not perfect.', array['otherwise']::text[], 'YDS · Contrast II', 32),
  ('Adding & Explaining', 'B2', 15, 1, 'as well as', '-in yanı sıra, ile birlikte', 'conjunction', 'She plays the piano as well as the guitar.', 'Gitarın yanı sıra piyano da çalıyor.', 'Bir şeyin yanına başkasını ekler. Özne olarak kullanılırsa fiil ilk özneye uyar: Tom, as well as his friends, is coming.', array['in addition to', 'besides']::text[], 'YDS · Adding & Explaining', 33),
  ('Adding & Explaining', 'B2', 15, 2, 'furthermore', 'üstelik, dahası', 'adverb', 'The flat is cheap. Furthermore, it is near the metro.', 'Daire ucuz. Üstelik metroya yakın.', 'Bir bilgiye başka bir bilgi ekler. "moreover" ve "what is more" ile aynıdır, yazıda sık kullanılır.', array['moreover', 'what is more']::text[], 'YDS · Adding & Explaining', 33),
  ('Adding & Explaining', 'B2', 15, 3, 'likewise', 'aynı şekilde, benzer biçimde', 'adverb', 'She helped us, and we did likewise.', 'O bize yardım etti, biz de aynısını yaptık.', 'Önceki bilgiyle benzerlik kurar. "similarly" ile aynıdır.', array['similarly', 'in the same way']::text[], 'YDS · Adding & Explaining', 33),
  ('Adding & Explaining', 'B2', 15, 4, 'in other words', 'başka bir deyişle', 'adverb', 'He is a vegan. In other words, he eats no animal products.', 'O vegan. Başka bir deyişle hayvansal ürün yemiyor.', 'Bir şeyi daha açık biçimde yeniden anlatmak için kullanılır.', array['that is to say', 'namely']::text[], 'YDS · Adding & Explaining', 33),
  ('Adding & Explaining', 'B2', 15, 5, 'in fact', 'aslında, gerçekte', 'adverb', 'I like him. In fact, I admire him.', 'Onu seviyorum. Hatta ona hayranım.', 'Bir bilgiyi pekiştirir veya düzeltir. "indeed" ve "as a matter of fact" ile aynı anlamdadır.', array['indeed', 'as a matter of fact']::text[], 'YDS · Adding & Explaining', 33),
  ('Emphasis & Manner', 'B2', 16, 1, 'just as', 'tıpkı ... gibi', 'conjunction', 'Just as water is vital, so is air.', 'Su nasıl hayati ise hava da öyledir.', 'İki şeyin benzerliğini vurgular. "just as ... so ..." kalıbı sık kullanılır. Zaman anlamıyla "tam o sırada" demektir: Just as I left, it rained.', array['in the same way as']::text[], 'YDS · Emphasis & Manner', 34),
  ('Emphasis & Manner', 'B2', 16, 2, 'rather', 'oldukça; -ektense', 'adverb', 'It was rather cold yesterday.', 'Dün oldukça soğuktu.', 'Derece bildirir (oldukça). "rather than" ile karşılaştırma yapar: He walked rather than drove.', array['quite', 'fairly']::text[], 'YDS · Emphasis & Manner', 34),
  ('Emphasis & Manner', 'B2', 16, 3, 'for fear that', '-dığı korkusuyla', 'conjunction', 'She whispered for fear that someone would hear.', 'Biri duyar korkusuyla fısıldadı.', 'Önlem alınan bir kaygıyı anlatır. "lest" ile aynıdır ve genelde "should" veya yalın fiille kullanılır: lest he should fall.', array['lest']::text[], 'YDS · Emphasis & Manner', 34),
  ('Emphasis & Manner', 'B2', 16, 4, 'as if', 'sanki', 'conjunction', 'He talks as if he knew everything.', 'Her şeyi biliyormuş gibi konuşuyor.', 'Gerçek dışı veya olası benzetme yapar. Gerçek dışılıkta Past Simple kullanılır: as if he were rich. "as though" aynıdır.', array['as though']::text[], 'YDS · Emphasis & Manner', 34),
  ('Emphasis & Manner', 'B2', 16, 5, 'notably', 'özellikle, dikkat çekici biçimde', 'adverb', 'Many countries, notably Japan, have aging populations.', 'Birçok ülkede, özellikle Japonya''da, nüfus yaşlanıyor.', 'Bir örneği öne çıkarır. Resmi yazıda sık geçer.', array['especially', 'in particular']::text[], 'YDS · Emphasis & Manner', 34),
  ('Focus & Summary', 'C1', 9, 1, 'in particular', 'özellikle', 'adverb', 'I like fruit, apples in particular.', 'Meyveyi severim, özellikle elmayı.', 'Bir şeyi diğerlerinden ayırıp vurgular. "particularly" ile aynı anlamdadır.', array['particularly', 'especially']::text[], 'YDS · Focus & Summary', 35),
  ('Focus & Summary', 'C1', 9, 2, 'to summarize', 'özetlemek gerekirse', 'adverb', 'To summarize, the plan has three steps.', 'Özetlemek gerekirse planın üç adımı var.', 'Konuşma veya yazının sonunda ana noktaları toparlamak için kullanılır. "all in all" ve "in short" benzerdir.', array['all in all', 'in short']::text[], 'YDS · Focus & Summary', 35),
  ('Focus & Summary', 'C1', 9, 3, 'with regard to', '-e ilişkin, -e gelince', 'preposition', 'With regard to your request, we will reply soon.', 'Talebinize ilişkin kısa sürede yanıt vereceğiz.', 'Resmi yazışmada konuyu belirtir. "with respect to" ve "in regard to" aynıdır, "in regards to" yanlış sayılır.', array['with respect to', 'in regard to']::text[], 'YDS · Focus & Summary', 35),
  ('Focus & Summary', 'C1', 9, 4, 'in terms of', 'açısından, bakımından', 'preposition', 'In terms of price, this phone is the best.', 'Fiyat açısından bu telefon en iyisi.', 'Bir konuyu belirli bir yönden ele alır. Arkasından isim veya -ing gelir.', array['regarding']::text[], 'YDS · Focus & Summary', 35),
  ('Focus & Summary', 'C1', 9, 5, 'concerning', '-e ilişkin, hakkında', 'preposition', 'He asked questions concerning safety.', 'Güvenlikle ilgili sorular sordu.', '"about" sözcüğünün resmi hâlidir. "regarding" ile aynıdır.', array['regarding', 'about']::text[], 'YDS · Focus & Summary', 35),
  ('Topic Phrases', 'B2', 17, 1, 'as for', '-e gelince', 'preposition', 'As for me, I prefer tea.', 'Bana gelince, ben çayı tercih ederim.', 'Konuyu değiştirip yeni bir kişi veya şeyden bahsetmek için kullanılır.', array['as to', 'regarding']::text[], 'YDS · Topic Phrases', 36),
  ('Topic Phrases', 'B2', 17, 2, 'with a view to', 'amacıyla, niyetiyle', 'preposition', 'He saved money with a view to buying a house.', 'Ev almak amacıyla para biriktirdi.', 'Arkasından -ing gelir. "with the aim of" ile aynıdır, buradaki "to" bir edattır.', array['with the aim of', 'in order to']::text[], 'YDS · Topic Phrases', 36),
  ('Topic Phrases', 'B2', 17, 3, 'twice as … as', 'iki kat ... kadar', 'phrase', 'This room is twice as big as mine.', 'Bu oda benimkinden iki kat büyük.', 'Katlı karşılaştırma yapar: twice, three times, half + as + sıfat + as.', array['two times as … as']::text[], 'YDS · Topic Phrases', 36),
  ('Topic Phrases', 'B2', 17, 4, 'half as … as', 'yarı kadar', 'phrase', 'This bag is half as heavy as that one.', 'Bu çanta ötekinin yarısı kadar ağır.', 'Yarım katlı karşılaştırma yapar. "not half as good as" hiç de o kadar iyi değil demektir.', '{}'::text[], 'YDS · Topic Phrases', 36),
  ('Topic Phrases', 'B2', 17, 5, 'so that', '-mesi için, böylece', 'conjunction', 'Speak slowly so that everyone can understand.', 'Herkes anlasın diye yavaş konuş.', 'Amaç bildirir. Arkasından can, could, will, would gelir. "in order that" ile aynıdır.', array['in order that']::text[], 'YDS · Topic Phrases', 36),
  ('Useful Structures', 'B2', 18, 1, 'manage to', 'başarmak, becermek', 'verb', 'She managed to finish on time.', 'Zamanında bitirmeyi başardı.', 'Zor bir şeyi başarmayı anlatır. Arkasından "to + fiil" gelir. Çabayı değil başarılan sonucu bildirir.', array['succeed in', 'be able to']::text[], 'YDS · Useful Structures', 37),
  ('Useful Structures', 'B2', 18, 2, 'might as well', '... da olur, ... de yapabiliriz', 'phrase', 'We might as well go home.', 'Eve de gidebiliriz (başka yapacak bir şey yok).', 'Başka iyi seçenek yokken yapılacak şeyi söyler. Sonrasında yalın fiil gelir. "may as well" aynıdır.', array['may as well']::text[], 'YDS · Useful Structures', 37),
  ('Useful Structures', 'B2', 18, 3, 'would rather', '-meyi tercih ederdim', 'phrase', 'I would rather stay at home.', 'Evde kalmayı tercih ederim.', 'Tercih bildirir. Arkasından yalın fiil gelir. Başka bir özne için Past Simple kullanılır: I''d rather you stayed.', array['prefer to', 'would prefer to']::text[], 'YDS · Useful Structures', 37),
  ('Useful Structures', 'B2', 18, 4, 'at the end of', '-in sonunda', 'preposition', 'At the end of the film, everyone clapped.', 'Filmin sonunda herkes alkışladı.', 'Bir şeyin son noktasını belirtir. "in the end" ise "sonunda" anlamında bir zarftır.', '{}'::text[], 'YDS · Useful Structures', 37),
  ('Useful Structures', 'B2', 18, 5, 'that of', '-ninki', 'phrase', 'The climate here is milder than that of Ankara.', 'Buranın iklimi Ankara''nınkinden daha ılıman.', 'Tekrardan kaçınmak için tekil bir ismin yerine kullanılır. Çoğul isim için "those of" kullanılır.', array['those of']::text[], 'YDS · Useful Structures', 37),
  ('More Prepositions', 'B2', 19, 1, 'through', 'içinden, boyunca, sayesinde', 'preposition', 'We walked through the forest.', 'Ormanın içinden yürüdük.', 'Bir yerin içinden geçişi anlatır. Aracı olarak da kullanılır: I found the job through a friend.', array['by means of']::text[], 'YDS · More Prepositions', 38),
  ('More Prepositions', 'B2', 19, 2, 'across', 'karşısına, bir yanından diğerine', 'preposition', 'He swam across the river.', 'Nehri yüzerek geçti.', 'Bir yüzeyin bir kenarından diğer kenarına geçişi anlatır. "across from" karşısında demektir.', array['over']::text[], 'YDS · More Prepositions', 38),
  ('More Prepositions', 'B2', 19, 3, 'along', 'boyunca', 'preposition', 'They walked along the beach.', 'Sahil boyunca yürüdüler.', 'Bir çizgi veya yol boyunca hareketi anlatır: along the river, along the road.', array['alongside']::text[], 'YDS · More Prepositions', 38),
  ('More Prepositions', 'B2', 19, 4, 'against', 'karşı, -e dayalı', 'preposition', 'He leaned against the wall.', 'Duvara yaslandı.', 'Hem karşıtlık (against the law) hem temas (against the wall) anlatır. "for" sözcüğünün zıttıdır.', array['opposed to']::text[], 'YDS · More Prepositions', 38),
  ('More Prepositions', 'B2', 19, 5, 'contrary to', '-in aksine', 'preposition', 'Contrary to popular belief, bats are not blind.', 'Yaygın inanışın aksine yarasalar kör değildir.', 'Beklenen veya bilinen şeyin tersini söyler. "in contrast to" ile aynı anlamdadır.', array['unlike', 'opposite to']::text[], 'YDS · More Prepositions', 38),
  ('Take Phrasal Verbs', 'B2', 20, 1, 'take off', 'havalanmak, çıkarmak', 'phrasal verb', 'The plane took off at nine.', 'Uçak dokuzda havalandı.', 'Birçok anlamı vardır: havalanmak, giysiyi çıkarmak, birdenbire popüler olmak, izin almak.', array['depart', 'remove']::text[], 'YDS · Take Phrasal Verbs', 39),
  ('Take Phrasal Verbs', 'B2', 20, 2, 'take in', 'anlamak, kavramak; kandırmak', 'phrasal verb', 'I couldn''t take in everything he said.', 'Söylediği her şeyi kavrayamadım.', 'Anlamak, barındırmak, aldatmak (be taken in) ve giysiyi daraltmak anlamlarında kullanılır.', array['absorb', 'understand']::text[], 'YDS · Take Phrasal Verbs', 39),
  ('Take Phrasal Verbs', 'B2', 20, 3, 'take on', 'üstlenmek, işe almak', 'phrasal verb', 'She took on extra work.', 'Ekstra iş üstlendi.', 'Sorumluluk veya iş üstlenmek, birini işe almak ve bir görünüm kazanmak anlamlarında kullanılır.', array['accept', 'hire']::text[], 'YDS · Take Phrasal Verbs', 39),
  ('Take Phrasal Verbs', 'B2', 20, 4, 'take out', 'çıkarmak, dışarı çıkarmak', 'phrasal verb', 'He took out his phone.', 'Telefonunu çıkardı.', 'Bir şeyi içinden çıkarmak, kredi veya sigorta yaptırmak (take out a loan) ve birini davet etmek anlamlarına gelir.', array['remove', 'extract']::text[], 'YDS · Take Phrasal Verbs', 39),
  ('Take Phrasal Verbs', 'B2', 20, 5, 'take over', 'devralmak, ele geçirmek', 'phrasal verb', 'He took over the company from his father.', 'Şirketi babasından devraldı.', 'Bir görevi, işi veya kontrolü başkasından almayı anlatır. İsmi: takeover.', array['assume control of', 'seize']::text[], 'YDS · Take Phrasal Verbs', 39),
  ('Turn & Touch', 'B2', 21, 1, 'turn down', 'reddetmek; sesini kısmak', 'phrasal verb', 'She turned down the job offer.', 'İş teklifini reddetti.', 'Teklif ve daveti reddetmek veya ses ve ısıyı azaltmak anlamındadır. Zıttı: turn up (sesi açmak).', array['reject', 'refuse']::text[], 'YDS · Turn & Touch', 40),
  ('Turn & Touch', 'B2', 21, 2, 'turn up', 'ortaya çıkmak, gelmek; sesini açmak', 'phrasal verb', 'He turned up late for the meeting.', 'Toplantıya geç geldi.', 'Beklenmedik biçimde ortaya çıkmak veya bir şeyi bulmak anlamındadır. Ses ya da ısıyı artırmak için de kullanılır.', array['arrive', 'appear']::text[], 'YDS · Turn & Touch', 40),
  ('Turn & Touch', 'B2', 21, 3, 'touch on', 'kısaca değinmek', 'phrasal verb', 'The speaker touched on several issues.', 'Konuşmacı birkaç konuya kısaca değindi.', 'Bir konuyu ayrıntıya girmeden anmayı anlatır.', array['mention', 'refer to']::text[], 'YDS · Turn & Touch', 40),
  ('Turn & Touch', 'B2', 21, 4, 'take stock', 'durum değerlendirmesi yapmak', 'phrasal verb', 'It''s time to take stock of what we have achieved.', 'Neler başardığımızı değerlendirme zamanı.', 'Durup düşünerek genel bir değerlendirme yapmayı anlatır. Arkasından "of" gelir.', array['assess', 'review']::text[], 'YDS · Turn & Touch', 40),
  ('Turn & Touch', 'B2', 21, 5, 'branch out', 'faaliyet alanını genişletmek', 'phrasal verb', 'The bakery decided to branch out into coffee.', 'Fırın kahve işine de açılmaya karar verdi.', 'Uğraşılan alana yeni bir alan eklemeyi anlatır: branch out into / to.', array['diversify', 'expand']::text[], 'YDS · Turn & Touch', 40),
  ('More Phrasal Verbs', 'B2', 22, 1, 'catch up', 'yetişmek, aradaki farkı kapatmak', 'phrasal verb', 'I have to catch up on my reading.', 'Okumalarımı yetiştirmem lazım.', 'Geri kalmış olanı yakalamak veya biriyle yetişmek: catch up with someone, catch up on something.', array['keep pace', 'draw level']::text[], 'YDS · More Phrasal Verbs', 41),
  ('More Phrasal Verbs', 'B2', 22, 2, 'make up', 'uydurmak, barışmak, oluşturmak', 'phrasal verb', 'He made up an excuse.', 'Bir bahane uydurdu.', 'Birçok anlamı vardır: uydurmak, barışmak, bir bütünü oluşturmak, makyaj yapmak ve (make up for) telafi etmek.', array['invent', 'form']::text[], 'YDS · More Phrasal Verbs', 41),
  ('More Phrasal Verbs', 'B2', 22, 3, 'zero in on', 'odaklanmak, tam hedefe yönelmek', 'phrasal verb', 'The police zeroed in on the main suspect.', 'Polis ana şüpheliye odaklandı.', 'Dikkati veya çabayı belirli bir hedefe yoğunlaştırmayı anlatır.', array['focus on', 'home in on']::text[], 'YDS · More Phrasal Verbs', 41),
  ('More Phrasal Verbs', 'B2', 22, 4, 'weather', 'atlatmak, dayanıp geçmek', 'verb', 'The company weathered the crisis.', 'Şirket krizi atlattı.', 'Zor bir dönemi sağ salim geçirmek anlamındadır: weather the storm, weather the crisis. Genelde doğrudan nesne alır, "weather out" yaygın bir kullanım değildir.', array['survive', 'ride out']::text[], 'YDS · More Phrasal Verbs', 41)
),
guarded as (
  select * from seed where not exists (select 1 from public.decks d where d.title = seed.deck_title)
),
new_decks as (
  insert into public.decks (title, category, level, position)
  select distinct deck_title, 'general'::public.deck_category, level::public.cefr_level, deck_position
  from guarded
  returning id, title
),
new_yds_decks as (
  insert into public.decks (title, category, level, position)
  select distinct yds_title, 'yds'::public.deck_category, null::public.cefr_level, yds_position
  from guarded
  returning id, title
),
new_words as (
  insert into public.words (english, turkish, part_of_speech, example_en, example_tr, usage_note, level, synonyms)
  select english, turkish, part_of_speech, example_en, example_tr, usage_note, level::public.cefr_level, synonyms
  from guarded
  returning id, english
),
level_links as (
  insert into public.deck_words (deck_id, word_id, position)
  select d.id, w.id, g.word_position
  from guarded g
  join new_decks d on d.title = g.deck_title
  join new_words w on w.english = g.english
  returning 1
)
insert into public.deck_words (deck_id, word_id, position)
select y.id, w.id, g.word_position
from guarded g
join new_yds_decks y on y.title = g.yds_title
join new_words w on w.english = g.english;
